/* Tạo tự động từ scripts/luyen-phat-am/content.js — đừng sửa tay. */
window.PA_DATA=[{"w":1,"code":"PRON-001","g":"Âm cuối","s":"Âm cuối /t/","t":"Hometown","tv":"Quê hương","x":["Tiếng Việt không bật âm cuối nên em hay đọc “street” thành “stri”, “night” thành “nai”.","Cách đọc: đầu lưỡi chạm lợi ngay sau răng trên, chặn hơi rồi bật nhẹ /t/. Không thêm “ờ” phía sau.","Đọc hết nguyên âm rồi mới chạm lưỡi: “nai…t”, “stri…t”.","Mẹo: đặt tay trước miệng, phải thấy một luồng hơi nhỏ khi bật /t/."],"k":[{"t":"street","ipa":"/striːt/","vi":"con phố","a":"d3a9fb075d49"},{"t":"market","ipa":"/ˈmɑːkɪt/","vi":"chợ","a":"5c9f73af7333"},{"t":"quiet","ipa":"/ˈkwaɪət/","vi":"yên tĩnh","a":"58bdb05d89f5"},{"t":"coast","ipa":"/kəʊst/","vi":"bờ biển","a":"366eb327e240"},{"t":"heat","ipa":"/hiːt/","vi":"cái nóng","a":"853911dc66c6"},{"t":"night","ipa":"/naɪt/","vi":"ban đêm","a":"1be2a44cb53d"},{"t":"visit","ipa":"/ˈvɪzɪt/","vi":"thăm","a":"a41f18cb110c"},{"t":"great","ipa":"/ɡreɪt/","vi":"tuyệt vời","a":"fbc8fae6b139"}],"r":[],"q":[{"q":"Where is your hometown?","qa":"3b1a3da40273","s":[{"t":"I come from a small town on the coast, about two hours east of the capital.","a":"7edf24ae7224"},{"t":"It's quite quiet, but most people know it for its night market.","a":"1252268a152c"}]},{"q":"What do you like most about your hometown?","qa":"9e1ec9ae2b96","s":[{"t":"The best part is the street food.","a":"021e9ee1a572"},{"t":"There's a night market right next to my street.","a":"40b6027154ca"},{"t":"I eat out there almost every weekend.","a":"cb8a8eecf7c1"}]},{"q":"Has your hometown changed much?","qa":"8aedbab84c54","s":[{"t":"Yes, quite a lot.","a":"9924e7434dac"},{"t":"They've built a new market and a sports centre, so it's not as quiet as it was.","a":"60977bb9b5f1"},{"t":"The summer heat is still hard to put up with, though.","a":"b4092de488a8"}]}]},{"w":2,"code":"PRON-002","g":"Âm cuối","s":"Âm cuối /d/","t":"Home","tv":"Nhà ở","x":["Em hay bỏ /d/ cuối: “road” thành “râu”, “food” thành “phu”, hoặc đọc thành /t/.","Cách đọc: lưỡi đặt như /t/ (chạm lợi trên) nhưng rung cổ và bật rất nhẹ.","Nguyên âm trước /d/ kéo dài hơn trước /t/: “bed” dài hơn “bet”.","Đừng thêm “ờ”: “old”, không phải “ôn-đờ”."],"k":[{"t":"bed","ipa":"/bed/","vi":"giường","a":"fefe2393a7fc"},{"t":"road","ipa":"/rəʊd/","vi":"con đường","a":"4adfa5797f24"},{"t":"old","ipa":"/əʊld/","vi":"cũ","a":"c00dbbc9dadf"},{"t":"food","ipa":"/fuːd/","vi":"đồ ăn","a":"39ccb32d95ed"},{"t":"side","ipa":"/saɪd/","vi":"phía, bên","a":"160cefc1ad7e"},{"t":"yard","ipa":"/jɑːd/","vi":"sân","a":"3ce2e832336a"},{"t":"crowded","ipa":"/ˈkraʊdɪd/","vi":"đông đúc","a":"8bd8c4facee3"},{"t":"inside","ipa":"/ˌɪnˈsaɪd/","vi":"bên trong","a":"fcc537881cd1"}],"r":[],"q":[{"q":"Do you live in a house or a flat?","qa":"56b964550cce","s":[{"t":"I live in an old house on a wide road, not far from the city centre.","a":"bc2f59603daf"},{"t":"It has a small yard at the side where my dad keeps his plants.","a":"76b98f52ecfd"}]},{"q":"What's your favourite room?","qa":"6355690fd506","s":[{"t":"My bedroom, without a doubt.","a":"f1a558050377"},{"t":"I've got a good bed and a desk beside the window.","a":"50e24eb4510c"},{"t":"Nobody disturbs me there while I read.","a":"30bcd16b59d7"}]},{"q":"Would you like to move in the future?","qa":"4947fbce727f","s":[{"t":"Maybe one day.","a":"0ab2b92d7c0f"},{"t":"Our road has become really crowded, and I'd like a place with a bigger yard.","a":"b375fa0f1930"},{"t":"I'd still stay on this side of town, though.","a":"47cb5191a4ea"}]}]},{"w":3,"code":"PRON-003","g":"Âm cuối","s":"Âm cuối /k/","t":"Study","tv":"Việc học","x":["Em hay nuốt /k/ cuối: “book” thành “bu”, “week” thành “uy”, “work” thành “quơ”.","Cách đọc: cuống lưỡi nâng lên chạm vòm mềm, chặn hơi rồi bật nhẹ /k/.","Miệng không khép môi lại như âm “c” cuối của tiếng Việt (“học”). Phải nghe thấy tiếng bật.","Tập đôi: “wee – week”, “boo – book”, “brea – break”."],"k":[{"t":"book","ipa":"/bʊk/","vi":"sách","a":"e7e694c58cd5"},{"t":"week","ipa":"/wiːk/","vi":"tuần","a":"c0ee32d825d6"},{"t":"break","ipa":"/breɪk/","vi":"giờ nghỉ","a":"4f9cac8dbc4c"},{"t":"check","ipa":"/tʃek/","vi":"kiểm tra","a":"d56d985300d4"},{"t":"think","ipa":"/θɪŋk/","vi":"nghĩ","a":"b7c61c80ab26"},{"t":"speak","ipa":"/spiːk/","vi":"nói","a":"a65265946e25"},{"t":"topic","ipa":"/ˈtɒpɪk/","vi":"chủ đề","a":"b415e16fbe4c"},{"t":"homework","ipa":"/ˈhəʊmwɜːk/","vi":"bài tập về nhà","a":"a264d337dcfe"}],"r":[],"q":[{"q":"What do you study?","qa":"f3fa12bf902c","s":[{"t":"I'm in my last year at high school, so I take a bit of everything.","a":"c4f4472072b6"},{"t":"The subject I like best is music, and I think I'll pick it at university.","a":"1f0c9b7319e0"}]},{"q":"When do you prefer to study?","qa":"b0fbe843661e","s":[{"t":"Early in the morning, before the rest of the house wakes up.","a":"42cc061cb8ad"},{"t":"I make a cup of tea and check my notebook.","a":"c10d94da90b4"},{"t":"Then I work for an hour without a break.","a":"893ef110c7b1"}]},{"q":"Is there anything you dislike about studying?","qa":"6a33a986e52b","s":[{"t":"Honestly, the homework.","a":"bbc15d86d908"},{"t":"We get a huge stack every week, and some of it doesn't make me think at all.","a":"bc0d37d36f9f"},{"t":"I'd rather pick one topic and look at it properly.","a":"ed318b1de913"}]}]},{"w":4,"code":"PRON-004","g":"Âm cuối","s":"Âm cuối /p/","t":"Work","tv":"Công việc","x":["Em hay bỏ /p/ cuối: “shop” thành “sóp” cụt hoặc “so”, “help” thành “heo”.","Cách đọc: mím hai môi lại chặn hơi, rồi mở môi bật nhẹ /p/. Không rung cổ.","Với “help”, phải có đủ /l/ rồi mới tới /p/: “hel…p”.","Tập đôi: “kee – keep”, “sto – stop”, “grou – group”."],"k":[{"t":"shop","ipa":"/ʃɒp/","vi":"cửa hàng","a":"5042d1466675"},{"t":"help","ipa":"/help/","vi":"giúp","a":"92005ecf3788"},{"t":"keep","ipa":"/kiːp/","vi":"giữ","a":"1264bdfe5ff3"},{"t":"stop","ipa":"/stɒp/","vi":"dừng","a":"1b480158e1f3"},{"t":"step","ipa":"/step/","vi":"bước","a":"bd370d1b6f9b"},{"t":"group","ipa":"/ɡruːp/","vi":"nhóm","a":"64292b1c2b2e"},{"t":"laptop","ipa":"/ˈlæptɒp/","vi":"máy tính xách tay","a":"e068381bbd9e"},{"t":"develop","ipa":"/dɪˈveləp/","vi":"phát triển","a":"418a6bc4decc"}],"r":[],"q":[{"q":"Do you work or are you a student?","qa":"a1395b4e62e6","s":[{"t":"I'm a student, but I've got a part-time job in a coffee shop.","a":"92695299528b"},{"t":"I help at the counter and keep the place tidy, mostly at weekends.","a":"42a060c0027f"}]},{"q":"What do you like about your job?","qa":"849e2d4bc19f","s":[{"t":"I like the group I work with.","a":"4650e5b3248f"},{"t":"If someone makes a slip, the others step in and help.","a":"127f198f6d61"},{"t":"It's taught me to keep calm, too.","a":"5ffe27d958dd"}]},{"q":"Would you like to change your job in the future?","qa":"b96875e9db7f","s":[{"t":"Yes, at some point.","a":"1f0b49692cdc"},{"t":"Serving coffee is fine for now, but I can't develop much there.","a":"81bec1237be6"},{"t":"I hope to set up a small online shop once I graduate.","a":"0242184b93ea"}]}]},{"w":5,"code":"PRON-005","g":"Âm cuối","s":"Đuôi -s / -es: /s/ · /z/ · /ɪz/","t":"Family","tv":"Gia đình","x":["Em hay bỏ hẳn đuôi -s, hoặc chỗ nào cũng đọc /s/.","Sau âm vô thanh /p t k f θ/ đọc /s/: parents, cooks. Sau âm hữu thanh và nguyên âm đọc /z/ (rung cổ): brothers, lives.","Sau /s z ʃ tʃ dʒ/ đọc thêm một âm tiết /ɪz/: watches, teaches.","Khi nói câu dài, đuôi -s vẫn phải nghe thấy, kể cả khi nói nhanh."],"k":[{"t":"parents","ipa":"/ˈpeərənts/","vi":"bố mẹ","a":"a664f10b5e58"},{"t":"cooks","ipa":"/kʊks/","vi":"nấu ăn","a":"692f4ec2ee76"},{"t":"brothers","ipa":"/ˈbrʌðəz/","vi":"anh em trai","a":"d419beaaa7ce"},{"t":"cousins","ipa":"/ˈkʌznz/","vi":"anh chị em họ","a":"b7ab6da658a4"},{"t":"lives","ipa":"/lɪvz/","vi":"sống","a":"25596ab9d8d1"},{"t":"watches","ipa":"/ˈwɒtʃɪz/","vi":"xem","a":"59fe6817258b"},{"t":"teaches","ipa":"/ˈtiːtʃɪz/","vi":"dạy","a":"d4d8137ec22b"},{"t":"notices","ipa":"/ˈnəʊtɪsɪz/","vi":"để ý","a":"51586ec65957"}],"r":[],"q":[{"q":"How many people are there in your family?","qa":"275faaefae54","s":[{"t":"There are five of us: my parents, my two brothers and me.","a":"b0b56770f97a"},{"t":"My grandmother lives with us as well, so the house always feels busy.","a":"ca7bc29a1253"}]},{"q":"What do you usually do together?","qa":"b6b04f2837c6","s":[{"t":"Not much on weekdays, to be honest.","a":"995bdfd6fbcf"},{"t":"But on Sundays my mum cooks a big lunch and my dad watches the football.","a":"226bb11e0b73"},{"t":"My cousins come round for games.","a":"3c2426011d9f"}]},{"q":"Who are you closest to?","qa":"65b9f7bcce18","s":[{"t":"Probably my older sister.","a":"5330c34d4af1"},{"t":"She teaches maths at a secondary school, and she always notices when something bothers me.","a":"a83c373ef4b7"},{"t":"She gives good advice and never judges.","a":"d3a4458a9ae9"}]}]},{"w":6,"code":"PRON-006","g":"Âm cuối","s":"Đuôi -ed: /t/ · /d/ · /ɪd/","t":"Friends","tv":"Bạn bè","x":["Em hay bỏ đuôi -ed, hoặc đọc “ít” ở mọi từ (“talk-ít”, “play-ít”).","Sau âm vô thanh đọc /t/: talked, laughed, watched. Sau âm hữu thanh và nguyên âm đọc /d/: played, moved, called.","Chỉ sau /t/ và /d/ mới thêm âm tiết /ɪd/: invited, decided.","“talked” chỉ có MỘT âm tiết: /tɔːkt/. Bật /k/ rồi /t/ liền nhau."],"k":[{"t":"talked","ipa":"/tɔːkt/","vi":"đã nói chuyện","a":"a2084a5ed709"},{"t":"laughed","ipa":"/lɑːft/","vi":"đã cười","a":"7541e444842a"},{"t":"watched","ipa":"/wɒtʃt/","vi":"đã xem","a":"2e04e93cf9dd"},{"t":"played","ipa":"/pleɪd/","vi":"đã chơi","a":"c1f3e1901b94"},{"t":"moved","ipa":"/muːvd/","vi":"đã chuyển","a":"5e142a4b65eb"},{"t":"called","ipa":"/kɔːld/","vi":"đã gọi","a":"970eeb47b2d0"},{"t":"invited","ipa":"/ɪnˈvaɪtɪd/","vi":"đã mời","a":"200b57390a8a"},{"t":"decided","ipa":"/dɪˈsaɪdɪd/","vi":"đã quyết định","a":"d4b8ee99930d"}],"r":[],"q":[{"q":"Do you have a lot of friends?","qa":"616354539852","s":[{"t":"Not a lot, but the ones I have are close.","a":"002fab1f44cf"},{"t":"Most of them lived on my street and played with me when we were kids.","a":"360e1803aa07"},{"t":"We've shared a lot since then.","a":"373f5d4a0774"}]},{"q":"How did you meet your best friend?","qa":"09c7c3cbba69","s":[{"t":"We were placed at the same desk in year six.","a":"2b3389bb29a3"},{"t":"I helped her with maths, and she invited me to her birthday.","a":"e6f090579c01"},{"t":"We ended up talking every day after that.","a":"d32eddabe738"}]},{"q":"What did you do the last time you met your friends?","qa":"51a1d3bcda11","s":[{"t":"Last Saturday we watched a film at my place and ordered pizza.","a":"ff0a50547f01"},{"t":"Then we talked and laughed until midnight.","a":"751c8e054a7a"},{"t":"Nobody wanted to go home.","a":"01b20e34854a"}]}]},{"w":7,"code":"PRON-007","g":"Âm cuối","s":"Âm cuối /l/","t":"Daily routine","tv":"Thói quen hằng ngày","x":["Em hay đọc /l/ cuối thành “u/o” hoặc “n”: “school” thành “sờ-cu”, “feel” thành “phiu”, “bell” thành “ben”.","Cách đọc: đầu lưỡi phải chạm lợi sau răng trên và GIỮ ở đó, hơi thoát hai bên lưỡi.","Môi không tròn lại. Nếu môi chu ra là em đang đọc “u”.","Tập: kéo dài “lllll” ở cuối từ: “schoolll”, “mealll”, “stilll”."],"k":[{"t":"school","ipa":"/skuːl/","vi":"trường học","a":"655f83be7512"},{"t":"meal","ipa":"/miːl/","vi":"bữa ăn","a":"8504d96b1782"},{"t":"bell","ipa":"/bel/","vi":"cái chuông","a":"04bf886e8ac2"},{"t":"feel","ipa":"/fiːl/","vi":"cảm thấy","a":"ccfcd3664e19"},{"t":"still","ipa":"/stɪl/","vi":"vẫn","a":"677c1bfa3a03"},{"t":"until","ipa":"/ənˈtɪl/","vi":"cho đến khi","a":"b310f4d4d89b"},{"t":"simple","ipa":"/ˈsɪmpl/","vi":"đơn giản","a":"0f7d0d088b6e"},{"t":"mobile","ipa":"/ˈməʊbaɪl/","vi":"điện thoại di động","a":"83d6311e87d4"}],"r":[],"q":[{"q":"What time do you usually get up?","qa":"5c018c5a5630","s":[{"t":"Around six on school days.","a":"ad7b1c4a086e"},{"t":"My alarm goes off like a bell, and I feel awful for the first ten minutes.","a":"cea36715b359"},{"t":"A cold shower and a small meal usually help.","a":"2446f26ea436"}]},{"q":"What's the busiest part of your day?","qa":"6aec965350b7","s":[{"t":"The afternoon, as a rule.","a":"3cf56a23e1ec"},{"t":"School doesn't finish until half past four, and then I still have an extra class.","a":"d2176a8794d8"},{"t":"All I want after that is a hot meal.","a":"2d6fe49301c7"}]},{"q":"Would you like to change your routine?","qa":"fb5433d1d4b0","s":[{"t":"A little, yes.","a":"c9eb2d5b38dd"},{"t":"I'd love to go to bed earlier, but I'm usually on my mobile until midnight.","a":"69ceabcbce94"},{"t":"A simple rule like no screens after ten would help a great deal.","a":"3334d834ee37"}]}]},{"w":8,"code":"PRON-008","g":"Âm cuối","s":"Âm cuối /n/ và /ŋ/","t":"Weekends","tv":"Cuối tuần","x":["Em hay lẫn hai âm này: “morning” đọc thành “mo-nin”, hoặc “town” thành “tao”.","/n/: đầu lưỡi chạm lợi trên. /ŋ/ (viết -ng): cuống lưỡi nâng chạm vòm mềm, đầu lưỡi nằm dưới.","Đuôi -ing luôn là /ɪŋ/, không bật thêm “g” và không đọc thành “in”.","Cả hai đều phải ngân qua mũi: “sunnn”, “longgg”."],"k":[{"t":"fun","ipa":"/fʌn/","vi":"vui","a":"c84c50d5a767"},{"t":"town","ipa":"/taʊn/","vi":"thị trấn, phố","a":"0cd0b19231db"},{"t":"garden","ipa":"/ˈɡɑːdn/","vi":"khu vườn","a":"b1ade531057f"},{"t":"long","ipa":"/lɒŋ/","vi":"dài","a":"bd3027fa569e"},{"t":"morning","ipa":"/ˈmɔːnɪŋ/","vi":"buổi sáng","a":"45a21e4b5b2a"},{"t":"evening","ipa":"/ˈiːvnɪŋ/","vi":"buổi tối","a":"d57fd91679ff"},{"t":"nothing","ipa":"/ˈnʌθɪŋ/","vi":"không gì cả","a":"0feca720e2c2"},{"t":"shopping","ipa":"/ˈʃɒpɪŋ/","vi":"mua sắm","a":"c651445273f6"}],"r":[],"q":[{"q":"What do you usually do at weekends?","qa":"861f6a391735","s":[{"t":"On Saturday morning I go swimming, and then I spend the afternoon in town with friends.","a":"7350d6134848"},{"t":"Sunday is for doing nothing, which is my favourite thing.","a":"229e4cfba498"}]},{"q":"Do you prefer staying in or going out?","qa":"45d39978d474","s":[{"t":"Going out, as long as it's not raining.","a":"19390ca1ff54"},{"t":"I love walking along the river in the evening.","a":"216b85094e79"},{"t":"The sun is going down then, and the town is calm.","a":"89f69100309b"}]},{"q":"What are you going to do next weekend?","qa":"6f0b96b65a4f","s":[{"t":"I'm planning a long bike ride with my cousin on Sunday morning.","a":"9bee026bd299"},{"t":"If it rains, we'll end up cooking something and watching films all evening.","a":"908a8fa963e0"}]}]},{"w":9,"code":"PRON-009","g":"Phụ âm khó","s":"Âm /θ/ (th vô thanh)","t":"Food","tv":"Đồ ăn","x":["Em hay đọc /θ/ thành “th” tiếng Việt, /t/ hoặc /s/: “three” thành “tri”, “think” thành “sink”.","Cách đọc: đưa đầu lưỡi ra giữa hai hàm răng, THỔI hơi qua khe lưỡi – răng. Không rung cổ.","Không chặn rồi bật như “th” tiếng Việt; hơi phải đi ra liên tục.","Soi gương: phải nhìn thấy đầu lưỡi."],"k":[{"t":"three","ipa":"/θriː/","vi":"số ba","a":"b802f384302c"},{"t":"thick","ipa":"/θɪk/","vi":"đặc, dày","a":"8fb4cd183e25"},{"t":"thanks","ipa":"/θæŋks/","vi":"cảm ơn","a":"6e3f5ad7c109"},{"t":"healthy","ipa":"/ˈhelθi/","vi":"lành mạnh","a":"de18ccfa15e8"},{"t":"something","ipa":"/ˈsʌmθɪŋ/","vi":"thứ gì đó","a":"1af17e73721d"},{"t":"birthday","ipa":"/ˈbɜːθdeɪ/","vi":"sinh nhật","a":"d98f2c581b10"},{"t":"both","ipa":"/bəʊθ/","vi":"cả hai","a":"fc39b18f287d"},{"t":"mouth","ipa":"/maʊθ/","vi":"miệng","a":"87d17825792d"}],"r":[{"t":"cooks","ipa":"/kʊks/","vi":"nấu ăn","a":"692f4ec2ee76","from":5},{"t":"market","ipa":"/ˈmɑːkɪt/","vi":"chợ","a":"5c9f73af7333","from":1}],"q":[{"q":"What kind of food do you like?","qa":"6239c2c910b4","s":[{"t":"I like anything with a thick, rich broth, so pho is my number one.","a":"435e9c43aa9a"},{"t":"I think I eat it three times a week, and I never get bored of it.","a":"f7f0affff3bd"}]},{"q":"Do you eat healthy food?","qa":"e559dfa3fd09","s":[{"t":"I try to.","a":"4a3808f7d48a"},{"t":"I have something healthy for breakfast and lunch, but dinner is another story.","a":"228b6436197a"},{"t":"Both my parents love fried food, and I can't say no.","a":"b9e74f1bd7b6"}]},{"q":"Is there any food you don't like?","qa":"6d78dc7bb270","s":[{"t":"Yes, I can't stand anything bitter.","a":"79ea760279ec"},{"t":"One mouthful of bitter melon and I need three glasses of water.","a":"350e17db2a28"},{"t":"My mum thinks it's healthy, but I'd rather go without.","a":"b8abeac1ebe9"}]}]},{"w":10,"code":"PRON-010","g":"Phụ âm khó","s":"Âm /ð/ (th hữu thanh)","t":"Shopping","tv":"Mua sắm","x":["Em hay đọc /ð/ thành /d/ hoặc /z/: “this” thành “đít”, “mother” thành “ma-đờ”.","Cách đọc: đầu lưỡi đặt giữa hai hàm răng như /θ/, nhưng RUNG cổ và đẩy hơi nhẹ.","Lưỡi không chạm lợi (đó là /d/). Đặt tay lên cổ phải thấy rung.","Các từ rất hay gặp: the, this, that, there, they, with, other."],"k":[{"t":"this","ipa":"/ðɪs/","vi":"cái này","a":"c2543fff3bfa"},{"t":"those","ipa":"/ðəʊz/","vi":"những cái kia","a":"6ccf720ae2a6"},{"t":"there","ipa":"/ðeə/","vi":"ở đó","a":"490528f36deb"},{"t":"other","ipa":"/ˈʌðə/","vi":"khác","a":"d0941e68da8f"},{"t":"mother","ipa":"/ˈmʌðə/","vi":"mẹ","a":"5116e40694ac"},{"t":"rather","ipa":"/ˈrɑːðə/","vi":"thà, hơn","a":"7e8b7811711c"},{"t":"together","ipa":"/təˈɡeðə/","vi":"cùng nhau","a":"9034ff9e2b8f"},{"t":"although","ipa":"/ɔːlˈðəʊ/","vi":"mặc dù","a":"dea713fc735e"}],"r":[{"t":"watched","ipa":"/wɒtʃt/","vi":"đã xem","a":"2e04e93cf9dd","from":6},{"t":"old","ipa":"/əʊld/","vi":"cũ","a":"c00dbbc9dadf","from":2}],"q":[{"q":"Do you like shopping?","qa":"bec886edce21","s":[{"t":"It depends on what I'm buying.","a":"cff26dd2a6ca"},{"t":"I'd rather not spend hours looking at clothes, although I'm happy to wander round a bookshop.","a":"922a3a159c24"},{"t":"That never feels like a waste of time.","a":"4032739cfc68"}]},{"q":"Who do you usually go shopping with?","qa":"ddec2693fca6","s":[{"t":"With my mother, most of the time.","a":"05764666f4a8"},{"t":"We go to the market together, and then she drags me into those little fabric shops.","a":"130c79cea6b6"},{"t":"I just stand there and carry the bags.","a":"b93c2b7f91c5"}]},{"q":"Do you prefer shopping online or in shops?","qa":"ebc74f469c4b","s":[{"t":"Online, for most things.","a":"14cf536f1f85"},{"t":"The prices are lower than in the shops, and there's more to choose from.","a":"251c1d6e5173"},{"t":"With shoes, though, I'd rather try them on first.","a":"b416ad0402bf"}]}]},{"w":11,"code":"PRON-011","g":"Phụ âm khó","s":"Âm /ʃ/ và /s/","t":"Clothes","tv":"Quần áo","x":["Nhiều em đọc /ʃ/ và /s/ giống nhau: “shoes” thành “su”, “short” thành “sót”.","/s/: môi dẹt, đầu lưỡi gần lợi trên, hơi xì mảnh và sắc.","/ʃ/: chu môi tròn, lưỡi lùi vào trong một chút, như tiếng “suỵt” bảo ai đó im lặng.","Tập đôi: “sue – shoe”, “sort – short”, “sock – shock”."],"k":[{"t":"shirt","ipa":"/ʃɜːt/","vi":"áo sơ mi","a":"faa5d6830269"},{"t":"shoes","ipa":"/ʃuːz/","vi":"giày","a":"19f319efbd6d"},{"t":"short","ipa":"/ʃɔːt/","vi":"ngắn","a":"a0f4ea7d9149"},{"t":"fashion","ipa":"/ˈfæʃn/","vi":"thời trang","a":"ed421c35417f"},{"t":"special","ipa":"/ˈspeʃl/","vi":"đặc biệt","a":"ba36b97a41e7"},{"t":"suit","ipa":"/suːt/","vi":"bộ com lê","a":"338ad11a14ea"},{"t":"socks","ipa":"/sɒks/","vi":"tất","a":"c9da8a6b0810"},{"t":"size","ipa":"/saɪz/","vi":"cỡ","a":"89368e1d6801"}],"r":[{"t":"feel","ipa":"/fiːl/","vi":"cảm thấy","a":"ccfcd3664e19","from":7},{"t":"check","ipa":"/tʃek/","vi":"kiểm tra","a":"d56d985300d4","from":3}],"q":[{"q":"What kind of clothes do you usually wear?","qa":"63eff86d9041","s":[{"t":"Simple stuff, mostly: a T-shirt, shorts and a pair of white shoes.","a":"6330a0ae4829"},{"t":"I only put on a proper shirt when the school asks us to.","a":"f5e3868c7ed8"}]},{"q":"Are you interested in fashion?","qa":"500d62099317","s":[{"t":"Not especially.","a":"f60f73062973"},{"t":"I notice what's in the shop windows, but I wouldn't say I chase fashion.","a":"3a70e953de5c"},{"t":"As long as the size is right and it's not too flashy, I'm satisfied.","a":"df9ae472165d"}]},{"q":"Do you ever wear special clothes?","qa":"2c1aeb8e0b69","s":[{"t":"Sure, on special occasions.","a":"aea4a2b254f5"},{"t":"At Tet I wear a silk ao dai.","a":"84af5a104470"},{"t":"Last summer I had to wear a suit for my sister's wedding, and I was boiling in it.","a":"42b5b9c99b3b"}]}]},{"w":12,"code":"PRON-012","g":"Phụ âm khó","s":"Âm /tʃ/ và /dʒ/","t":"Weather","tv":"Thời tiết","x":["Em hay đọc /tʃ/ nhẹ như “ch” tiếng Việt, và /dʒ/ thành “gi/d” mềm hoặc /z/.","Cả hai âm đều: chu môi, đầu lưỡi chạm lợi trên CHẶN hơi, rồi bật mạnh ra.","/tʃ/ không rung cổ (much, change). /dʒ/ rung cổ (June, enjoy).","Ở cuối từ càng phải bật rõ: “much”, “change” — không đọc “mắt”, “chên”."],"k":[{"t":"chilly","ipa":"/ˈtʃɪli/","vi":"se lạnh","a":"b8359f83459c"},{"t":"change","ipa":"/tʃeɪndʒ/","vi":"thay đổi","a":"7550b672e162"},{"t":"much","ipa":"/mʌtʃ/","vi":"nhiều","a":"7d3f44729dc2"},{"t":"temperature","ipa":"/ˈtemprətʃə/","vi":"nhiệt độ","a":"7033e90fcdda"},{"t":"June","ipa":"/dʒuːn/","vi":"tháng Sáu","a":"a9db90676169"},{"t":"July","ipa":"/dʒuˈlaɪ/","vi":"tháng Bảy","a":"df97a42549e5"},{"t":"jacket","ipa":"/ˈdʒækɪt/","vi":"áo khoác","a":"1cdbba9665ee"},{"t":"enjoy","ipa":"/ɪnˈdʒɔɪ/","vi":"thích, tận hưởng","a":"540e181495e5"}],"r":[{"t":"morning","ipa":"/ˈmɔːnɪŋ/","vi":"buổi sáng","a":"45a21e4b5b2a","from":8},{"t":"step","ipa":"/step/","vi":"bước","a":"bd370d1b6f9b","from":4}],"q":[{"q":"What's the weather like where you live?","qa":"763a7da22fa4","s":[{"t":"It changes a lot through the year.","a":"139ec872f1ad"},{"t":"June and July are boiling, with temperatures above thirty-five.","a":"70fcc52fbe50"},{"t":"Then January can be surprisingly chilly.","a":"b044eee33ec1"}]},{"q":"What's your favourite kind of weather?","qa":"4ed8c51efbc8","s":[{"t":"Cool and dry, which we get in the autumn.","a":"13cb349e2ffd"},{"t":"I can put on a light jacket and enjoy a walk without melting.","a":"26203e5f817e"},{"t":"It's such a nice change after the summer.","a":"fe159b490373"}]},{"q":"Does the weather affect your mood?","qa":"8d2b25d732a8","s":[{"t":"Very much.","a":"6b70d8bb211e"},{"t":"A few grey days in a row and I just want to stay in bed.","a":"c6a7db593f43"},{"t":"As soon as the sun's out again, I cheer up and have much more energy.","a":"8ccd03f8b7bc"}]}]},{"w":13,"code":"PRON-013","g":"Phụ âm khó","s":"Âm /z/","t":"Sports","tv":"Thể thao","x":["Em hay đọc /z/ thành /s/ hoặc “d” miền Bắc: “easy” thành “i-si”, “because” thành “bi-cót”.","Cách đọc: đặt lưỡi như /s/ nhưng RUNG cổ, nghe như tiếng ong “zzz”.","Chữ “s” rất hay đọc là /z/: busy, easy, because, always, games.","Đặt tay lên cổ: /s/ không rung, /z/ rung."],"k":[{"t":"easy","ipa":"/ˈiːzi/","vi":"dễ","a":"861c4f67e887"},{"t":"lazy","ipa":"/ˈleɪzi/","vi":"lười","a":"1078cf414b26"},{"t":"busy","ipa":"/ˈbɪzi/","vi":"bận","a":"e18a89f9cc5b"},{"t":"prize","ipa":"/praɪz/","vi":"giải thưởng","a":"92969bb9ea65"},{"t":"games","ipa":"/ɡeɪmz/","vi":"trò chơi, trận đấu","a":"dd27204535de"},{"t":"exercise","ipa":"/ˈeksəsaɪz/","vi":"tập thể dục","a":"eb70d1fcdf82"},{"t":"because","ipa":"/bɪˈkɒz/","vi":"bởi vì","a":"d1ef4731ec5c"},{"t":"always","ipa":"/ˈɔːlweɪz/","vi":"luôn luôn","a":"6656018ac96d"}],"r":[{"t":"birthday","ipa":"/ˈbɜːθdeɪ/","vi":"sinh nhật","a":"d98f2c581b10","from":9},{"t":"watches","ipa":"/ˈwɒtʃɪz/","vi":"xem","a":"59fe6817258b","from":5}],"q":[{"q":"Do you play any sports?","qa":"cc7cebab7170","s":[{"t":"I play badminton twice a week with my cousins.","a":"c4e216ea8cec"},{"t":"I'm not amazing at it, but it's easy to organise because there are courts near my house.","a":"63f95bac50d7"}]},{"q":"Did you do much sport as a child?","qa":"981d6f6c6348","s":[{"t":"Loads.","a":"f1f327ae9ed9"},{"t":"I was always outside, playing games with the boys next door.","a":"6aa1acd3c242"},{"t":"These days I'm busier and, to be honest, a bit lazier.","a":"711be9012f0c"}]},{"q":"Why do you think people enjoy watching sport?","qa":"439222e12a4e","s":[{"t":"Because it's exciting, and you never know who's going to win the prize.","a":"a37d61aa323e"},{"t":"It also gives friends and families a reason to get together at weekends.","a":"1420019bcce1"}]}]},{"w":14,"code":"PRON-014","g":"Phụ âm khó","s":"Âm /v/ và /w/","t":"Music","tv":"Âm nhạc","x":["Em hay đọc /v/ thành “v” nhẹ kiểu Việt hoặc /b/, và đọc /w/ thành “qu/u”.","/v/: răng trên chạm nhẹ môi dưới, đẩy hơi và rung cổ. Môi KHÔNG tròn.","/w/: chu môi tròn như “u” rồi mở nhanh ra, răng không chạm môi.","Tập đôi: “vet – wet”, “vine – wine”, “very well”."],"k":[{"t":"voice","ipa":"/vɔɪs/","vi":"giọng","a":"47ef65890ddb"},{"t":"very","ipa":"/ˈveri/","vi":"rất","a":"e74295bfc2ed"},{"t":"favourite","ipa":"/ˈfeɪvərɪt/","vi":"yêu thích","a":"824168b68d01"},{"t":"violin","ipa":"/ˌvaɪəˈlɪn/","vi":"đàn vi-ô-lông","a":"06384a70e1eb"},{"t":"live","ipa":"/laɪv/","vi":"trực tiếp","a":"98aadb37083e"},{"t":"words","ipa":"/wɜːdz/","vi":"lời, từ","a":"efb893611e6f"},{"t":"while","ipa":"/waɪl/","vi":"trong khi","a":"6517f89c46c3"},{"t":"well","ipa":"/wel/","vi":"tốt, hay","a":"bd8483287459"}],"r":[{"t":"together","ipa":"/təˈɡeðə/","vi":"cùng nhau","a":"9034ff9e2b8f","from":10},{"t":"invited","ipa":"/ɪnˈvaɪtɪd/","vi":"đã mời","a":"200b57390a8a","from":6}],"q":[{"q":"What kind of music do you like?","qa":"79d949157714","s":[{"t":"I'm very into V-pop at the moment.","a":"200d56acb300"},{"t":"My favourite singer has a warm, soft voice.","a":"d4ea32c0c750"},{"t":"Her words always seem to say what I'm feeling.","a":"6986aebf9efd"}]},{"q":"When do you usually listen to music?","qa":"169679d75e5a","s":[{"t":"Whenever I'm on the move, really.","a":"2c2da9e9377b"},{"t":"I've always got my headphones in while I'm walking to school.","a":"a073535df045"},{"t":"In the evening I play something quiet to wind down.","a":"cfa6b8f0aaa9"}]},{"q":"Have you ever been to a live concert?","qa":"aa0fa7abfd74","s":[{"t":"Just once.","a":"5a4cb8b363a7"},{"t":"I went with five friends to a live show last November, and we waited over an hour to get in.","a":"414723fb942c"},{"t":"It was well worth it, though.","a":"d3894da9be98"}]}]},{"w":15,"code":"PRON-015","g":"Phụ âm khó","s":"Âm /r/ và /l/","t":"Films","tv":"Phim ảnh","x":["Em hay đọc /r/ rung lưỡi kiểu Việt hoặc lẫn /r/ với /l/: “right” và “light” nghe giống nhau.","/r/: cong đầu lưỡi về phía sau, KHÔNG chạm vào đâu cả, môi hơi tròn.","/l/: đầu lưỡi chạm chắc vào lợi sau răng trên, hơi thoát hai bên.","Tập đôi: “right – light”, “read – lead”, “really”, “relax”."],"k":[{"t":"really","ipa":"/ˈriːəli/","vi":"thật sự","a":"084ab4093f67"},{"t":"right","ipa":"/raɪt/","vi":"đúng, ổn","a":"d27a1f117712"},{"t":"light","ipa":"/laɪt/","vi":"đèn, ánh sáng","a":"dfccc06f1441"},{"t":"role","ipa":"/rəʊl/","vi":"vai diễn","a":"8dca46428d00"},{"t":"release","ipa":"/rɪˈliːs/","vi":"phim mới ra, phát hành","a":"01f561ac4ab1"},{"t":"relax","ipa":"/rɪˈlæks/","vi":"thư giãn","a":"63bb094ca482"},{"t":"romantic","ipa":"/rəʊˈmæntɪk/","vi":"lãng mạn","a":"346f5986a97e"},{"t":"thriller","ipa":"/ˈθrɪlə/","vi":"phim li kì","a":"952a08c42349"}],"r":[{"t":"size","ipa":"/saɪz/","vi":"cỡ","a":"89368e1d6801","from":11},{"t":"mobile","ipa":"/ˈməʊbaɪl/","vi":"điện thoại di động","a":"83d6311e87d4","from":7}],"q":[{"q":"What kind of films do you like?","qa":"dec7bbf87c2e","s":[{"t":"I really like thrillers, especially ones with a clever plot.","a":"55ce9314fc8e"},{"t":"Romantic films are all right, but they rarely surprise me.","a":"affccc5a8577"}]},{"q":"How often do you go to the cinema?","qa":"f82c8da7a2d1","s":[{"t":"Roughly once a month.","a":"30c014720b4f"},{"t":"I look out for new releases and go with my brother, usually on a Friday.","a":"5022d14a54e2"},{"t":"It's a lovely way to relax after a long week.","a":"d6a2048b74ae"}]},{"q":"Is there a film you'd like to see again?","qa":"3d13376b18bc","s":[{"t":"Yes, Parasite.","a":"e0ee381d0c6d"},{"t":"The lead actor plays his role brilliantly, and I'm sure I missed a lot of little details.","a":"bbcb6fac08ca"},{"t":"I'd like to watch it again with the lights off.","a":"1f69b338b396"}]}]},{"w":16,"code":"PRON-016","g":"Phụ âm khó","s":"Âm đầu /p/ và /b/","t":"Reading","tv":"Đọc sách","x":["/p/ tiếng Việt không bật hơi nên “paper” của em nghe giống “baper”.","/p/ đầu từ: mím môi rồi bật ra một luồng HƠI mạnh, không rung cổ. Để tờ giấy trước miệng, giấy phải rung.","/b/: mím môi, rung cổ, không có luồng hơi.","Tập đôi: “pack – back”, “pie – buy”, “pear – bear”."],"k":[{"t":"paper","ipa":"/ˈpeɪpə/","vi":"giấy","a":"950593b1f42d"},{"t":"page","ipa":"/peɪdʒ/","vi":"trang","a":"767013ce0ee0"},{"t":"poem","ipa":"/ˈpəʊɪm/","vi":"bài thơ","a":"69d27e80a95a"},{"t":"popular","ipa":"/ˈpɒpjələ/","vi":"phổ biến","a":"99d637374f51"},{"t":"public","ipa":"/ˈpʌblɪk/","vi":"công cộng","a":"61c9b2b17db7"},{"t":"borrow","ipa":"/ˈbɒrəʊ/","vi":"mượn","a":"72cd0a82a0c7"},{"t":"boring","ipa":"/ˈbɔːrɪŋ/","vi":"chán","a":"2c7fba49380b"},{"t":"bookshop","ipa":"/ˈbʊkʃɒp/","vi":"hiệu sách","a":"4feb74066b53"}],"r":[{"t":"chilly","ipa":"/ˈtʃɪli/","vi":"se lạnh","a":"b8359f83459c","from":12},{"t":"fun","ipa":"/fʌn/","vi":"vui","a":"c84c50d5a767","from":8}],"q":[{"q":"Do you like reading?","qa":"432fc469c370","s":[{"t":"Yes, I'm a big reader.","a":"8ea52d28e578"},{"t":"I always keep a paperback in my bag, and I can't pass a bookshop without popping in.","a":"2bdb0963d656"},{"t":"It's probably my most expensive habit.","a":"6e557aabccb4"}]},{"q":"What kind of books did you read as a child?","qa":"9b29e340d5ff","s":[{"t":"Picture books at first, and then piles of comics.","a":"a7d70e412628"},{"t":"I used to borrow them from the public library and read them in bed.","a":"a35fb6472a0a"},{"t":"My parents had to beg me to put the light out.","a":"22609db2194e"}]},{"q":"Do you prefer paper books or e-books?","qa":"65cff86f8970","s":[{"t":"Paper, by a long way.","a":"09c92e2e8707"},{"t":"Reading on a screen feels a bit like work, and I get bored after a few pages.","a":"a2c5d4e2fa67"},{"t":"With a proper book, I can sit for hours.","a":"eaaf8f1fca57"}]}]},{"w":17,"code":"PRON-017","g":"Phụ âm khó","s":"Cụm phụ âm đầu (tr, dr, st, sp, pl, br…)","t":"Transport","tv":"Giao thông","x":["Em hay chêm “ờ” vào giữa cụm (“sờ-tây-sần”), hoặc bỏ bớt một âm (“train” thành “chên”, “plane” thành “pên”).","Đọc các phụ âm DÍNH liền nhau, không có nguyên âm ở giữa: /st/, /sp/, /pl/, /br/.","/tr/ và /dr/: bắt đầu bằng /t/, /d/ rồi cong lưỡi sang /r/ ngay — không đọc thành “ch”, “gi”.","Tập chậm rồi nhanh dần: “s…t…ation → station”, “t…rain → train”."],"k":[{"t":"train","ipa":"/treɪn/","vi":"tàu hoả","a":"94efdd6f628e"},{"t":"traffic","ipa":"/ˈtræfɪk/","vi":"giao thông","a":"c8ab51895da8"},{"t":"drive","ipa":"/draɪv/","vi":"lái xe","a":"4979d619a7b7"},{"t":"bridge","ipa":"/brɪdʒ/","vi":"cây cầu","a":"2fa1981b4a9a"},{"t":"plane","ipa":"/pleɪn/","vi":"máy bay","a":"2e869b90408c"},{"t":"speed","ipa":"/spiːd/","vi":"tốc độ","a":"92b6320812d8"},{"t":"station","ipa":"/ˈsteɪʃn/","vi":"nhà ga","a":"2da36ff30a38"},{"t":"straight","ipa":"/streɪt/","vi":"thẳng","a":"6ec09feb3f12"}],"r":[{"t":"lazy","ipa":"/ˈleɪzi/","vi":"lười","a":"1078cf414b26","from":13},{"t":"thick","ipa":"/θɪk/","vi":"đặc, dày","a":"8fb4cd183e25","from":9}],"q":[{"q":"How do you usually get around?","qa":"11df9696f2eb","s":[{"t":"By scooter, like most people here.","a":"108e4e5fe08b"},{"t":"It's quick, and I can slip through the traffic when the streets are blocked.","a":"b89a0af11075"},{"t":"I only take the bus when it's pouring.","a":"702e45203548"}]},{"q":"Do you ever travel by train?","qa":"805fd1ff7c63","s":[{"t":"Not often, but I love it when I do.","a":"99f64a6bb891"},{"t":"Last spring I took a sleeper train from Hanoi to Hue.","a":"238ae2fe514c"},{"t":"I spent the whole trip staring out of the window.","a":"5a6fc0865d69"}]},{"q":"What's the traffic like in your city?","qa":"4677b5b7856f","s":[{"t":"Pretty dreadful at rush hour.","a":"eb6e200d9afa"},{"t":"It can take twenty minutes just to cross the bridge near my school.","a":"bd95512c5f60"},{"t":"Things should speed up once the new station opens.","a":"210c933c2441"}]}]},{"w":18,"code":"PRON-018","g":"Phụ âm khó","s":"Cụm phụ âm cuối (-st, -kt, -ks, -ndz, -nθs…)","t":"Technology","tv":"Công nghệ","x":["Đây là lỗi nặng nhất của người Việt: “text” thành “téc”, “next” thành “néc”, “friends” thành “phen”.","Phải đọc ĐỦ từng phụ âm cuối theo thứ tự: text = /k/ + /s/ + /t/.","Tập ngược từ cuối: “t → st → kst → text”.","Nói chậm lại ở cuối từ còn hơn là nuốt mất âm."],"k":[{"t":"text","ipa":"/tekst/","vi":"nhắn tin","a":"372ea08cab33"},{"t":"next","ipa":"/nekst/","vi":"tiếp theo","a":"edee9402d198"},{"t":"desk","ipa":"/desk/","vi":"bàn học","a":"46e7cfa08091"},{"t":"post","ipa":"/pəʊst/","vi":"đăng bài","a":"9b466094ec99"},{"t":"apps","ipa":"/æps/","vi":"ứng dụng","a":"8025087a9e2e"},{"t":"friends","ipa":"/frendz/","vi":"bạn bè","a":"3d9209c4598b"},{"t":"months","ipa":"/mʌnθs/","vi":"tháng","a":"f1494311e45e"},{"t":"world","ipa":"/wɜːld/","vi":"thế giới","a":"7c211433f020"}],"r":[{"t":"favourite","ipa":"/ˈfeɪvərɪt/","vi":"yêu thích","a":"824168b68d01","from":14},{"t":"there","ipa":"/ðeə/","vi":"ở đó","a":"490528f36deb","from":10}],"q":[{"q":"What technology do you use most?","qa":"0efbcf52f4ab","s":[{"t":"My phone, by far.","a":"e23690a58a9c"},{"t":"I use it to text friends, check facts and watch clips.","a":"696121ae749b"},{"t":"It's the first thing I pick up when I wake up, which isn't great.","a":"c74880074c15"}]},{"q":"Do you spend too much time on screens?","qa":"af0a3501c78b","s":[{"t":"Probably, yes.","a":"77e4ed26586c"},{"t":"Between lessons, homework and chats, I'm at my desk for most of the day.","a":"3c40982cb85d"},{"t":"In the last few months I've tried to switch everything off by eleven.","a":"391e7ee93372"}]},{"q":"Is there a gadget you'd like to buy?","qa":"007ddbe398ca","s":[{"t":"I've got my eye on a pair of wireless headphones.","a":"f5b12f28701f"},{"t":"Mine broke last month, and the next model is meant to be excellent.","a":"8a499a685d3c"},{"t":"I just can't afford them yet.","a":"36cfb788fc82"}]}]},{"w":19,"code":"PRON-019","g":"Nguyên âm","s":"/ɪ/ ngắn và /iː/ dài","t":"Hobbies","tv":"Sở thích","x":["Em hay đọc hai âm này giống nhau, đều thành “i” tiếng Việt: “fit” và “feet” nghe như một.","/iː/: kéo dài, môi căng sang hai bên như cười, lưỡi nâng cao: “feeet”.","/ɪ/: ngắn, gọn, miệng thả lỏng, hơi ngả về “ê”: “fit”.","Tập đôi: “fit – feet”, “sit – seat”, “live – leave”."],"k":[{"t":"fit","ipa":"/fɪt/","vi":"khoẻ, vừa","a":"9c20b9ba55a2"},{"t":"feet","ipa":"/fiːt/","vi":"bàn chân","a":"67c0fccad5fd"},{"t":"swim","ipa":"/swɪm/","vi":"bơi","a":"b89f90f328fa"},{"t":"team","ipa":"/tiːm/","vi":"đội","a":"d25187dc137f"},{"t":"listen","ipa":"/ˈlɪsn/","vi":"nghe","a":"2147a9e5f9e8"},{"t":"free","ipa":"/friː/","vi":"rảnh, miễn phí","a":"4ff88aaddbd2"},{"t":"film","ipa":"/fɪlm/","vi":"phim","a":"ad363a93848b"},{"t":"cheap","ipa":"/tʃiːp/","vi":"rẻ","a":"fb8df41a16b4"}],"r":[{"t":"role","ipa":"/rəʊl/","vi":"vai diễn","a":"8dca46428d00","from":15},{"t":"fashion","ipa":"/ˈfæʃn/","vi":"thời trang","a":"ed421c35417f","from":11}],"q":[{"q":"What do you do in your free time?","qa":"86cbe775729a","s":[{"t":"I swim three evenings a week, which keeps me fit.","a":"98adf2f44a95"},{"t":"When I'm not in the pool, I listen to podcasts or watch a film with my sister.","a":"8dea4a09d470"}]},{"q":"Did you have the same hobbies as a child?","qa":"345b36636479","s":[{"t":"Not really.","a":"38a907a7fff5"},{"t":"I was in a little football team until I was fifteen, but I wasn't quick on my feet.","a":"336c125006f2"},{"t":"Swimming is a much better fit for me.","a":"415c4d1e4f56"}]},{"q":"Is it important to have a hobby?","qa":"a7a999329ce5","s":[{"t":"I think it is.","a":"ccc7a731c850"},{"t":"We all need something that isn't school or work.","a":"90bb14e6bcc6"},{"t":"It can be cheap, too: a library card is free, and it will keep you busy for weeks.","a":"e8098d21b990"}]}]},{"w":20,"code":"PRON-020","g":"Nguyên âm","s":"/æ/ và /e/","t":"Pets","tv":"Thú cưng","x":["Em hay đọc /æ/ thành “e” hoặc “a”: “cat” thành “két”, “bad” nghe như “bed”.","/æ/: há miệng RỘNG, hạ hàm, kéo khoé miệng sang hai bên — âm nằm giữa “a” và “e”.","/e/: miệng mở vừa, ngắn, giống “e” tiếng Việt.","Tập đôi: “bad – bed”, “pat – pet”, “man – men”."],"k":[{"t":"cat","ipa":"/kæt/","vi":"con mèo","a":"9d989e8d27dc"},{"t":"pet","ipa":"/pet/","vi":"thú cưng","a":"1b034c38bec0"},{"t":"happy","ipa":"/ˈhæpi/","vi":"vui","a":"3978d009748e"},{"t":"animal","ipa":"/ˈænɪml/","vi":"động vật","a":"3199ea056253"},{"t":"rabbit","ipa":"/ˈræbɪt/","vi":"con thỏ","a":"6d0ebbbdce32"},{"t":"friendly","ipa":"/ˈfrendli/","vi":"thân thiện","a":"41209342f361"},{"t":"vet","ipa":"/vet/","vi":"bác sĩ thú y","a":"cd57239bd6ed"},{"t":"many","ipa":"/ˈmeni/","vi":"nhiều","a":"f25470201a13"}],"r":[{"t":"public","ipa":"/ˈpʌblɪk/","vi":"công cộng","a":"61c9b2b17db7","from":16},{"t":"June","ipa":"/dʒuːn/","vi":"tháng Sáu","a":"a9db90676169","from":12}],"q":[{"q":"Do you have a pet?","qa":"d03595ecde21","s":[{"t":"Yes, a black and tan cat called Pepper.","a":"0650e9408270"},{"t":"We got her from a friend ten years ago, and she's very much a member of the family.","a":"4a93a219ff9c"}]},{"q":"What animals are popular as pets in your country?","qa":"9fd6ef6dc936","s":[{"t":"Cats and dogs, as you'd expect.","a":"16d261d1aec2"},{"t":"Lately, though, many young people in flats have rabbits or hamsters instead.","a":"7aa4d615f5bf"},{"t":"They're friendly, and they're less expensive to look after.","a":"4367c3c6dfee"}]},{"q":"Did you have a pet when you were a child?","qa":"a584ebec0936","s":[{"t":"Sadly, no.","a":"c93e61c542a2"},{"t":"My dad said animals were messy, and that was that.","a":"1e216844f3b3"},{"t":"My best friend had a rabbit, so I went round to pet it whenever I had the chance.","a":"159de8bd5682"}]}]},{"w":21,"code":"PRON-021","g":"Nguyên âm","s":"/ʌ/ và /ɑː/","t":"Colours","tv":"Màu sắc","x":["Em hay đọc /ʌ/ thành “â/ơ” hoặc “a”, và đọc /ɑː/ quá ngắn: “dark” thành “đác”.","/ʌ/: ngắn, miệng mở vừa, thả lỏng, gần “ă”: love, colour, sunny.","/ɑː/: há miệng rộng, lưỡi hạ thấp, KÉO DÀI: dark, calm, scarf. Giọng Anh không đọc “r” ở đây.","Tập đôi: “cut – cart”, “much – march”, “duck – dark”."],"k":[{"t":"colour","ipa":"/ˈkʌlə/","vi":"màu sắc","a":"79d41a47e8fe"},{"t":"love","ipa":"/lʌv/","vi":"yêu thích","a":"9f2feb0f1ef4"},{"t":"dull","ipa":"/dʌl/","vi":"xỉn, nhạt","a":"738a85cfbdd6"},{"t":"sunny","ipa":"/ˈsʌni/","vi":"nắng, tươi","a":"b892f067921d"},{"t":"dark","ipa":"/dɑːk/","vi":"tối, đậm","a":"3d09ba44760d"},{"t":"calm","ipa":"/kɑːm/","vi":"dịu, bình yên","a":"2ec3d0c752de"},{"t":"scarf","ipa":"/skɑːf/","vi":"khăn quàng","a":"a384cff1a369"},{"t":"grass","ipa":"/ɡrɑːs/","vi":"cỏ","a":"bbc29b76c59b"}],"r":[{"t":"speed","ipa":"/spiːd/","vi":"tốc độ","a":"92b6320812d8","from":17},{"t":"exercise","ipa":"/ˈeksəsaɪz/","vi":"tập thể dục","a":"eb70d1fcdf82","from":13}],"q":[{"q":"What's your favourite colour?","qa":"e427a9d04f14","s":[{"t":"Dark green, like grass after rain.","a":"7bb0e8214cac"},{"t":"It's a calm colour, and I've got far too much of it in my wardrobe.","a":"c8739197a833"}]},{"q":"Do you usually wear bright or dark colours?","qa":"da3282984a8d","s":[{"t":"Dark ones, nine times out of ten.","a":"278a5871c47f"},{"t":"Black and navy are hard to get wrong, and they don't show the dust.","a":"1a610554bd47"},{"t":"My mum says it's dull, so sometimes I add a red scarf.","a":"eecb39f09d1d"}]},{"q":"Are colours important when you buy something?","qa":"81dd6298cd2a","s":[{"t":"For some things, yes.","a":"b089f026aa6f"},{"t":"I'd never buy a car in a colour I didn't love, because I'd be stuck with it for years.","a":"1dead8ad8cb6"},{"t":"For a cup or a charger, I couldn't care less.","a":"9f593bd7ee9a"}]}]},{"w":22,"code":"PRON-022","g":"Nguyên âm","s":"/ʊ/ ngắn và /uː/ dài","t":"Photos","tv":"Ảnh","x":["Em hay đọc cả hai thành “u” tiếng Việt: “look” nghe như “Luke”, “good” thành “gút” kéo dài.","/uː/: chu môi tròn và nhọn, kéo dài: zoom, blue, view.","/ʊ/: ngắn, môi chỉ hơi tròn, thả lỏng, hơi ngả về “ơ”: look, good, took, put.","Tập đôi: “pull – pool”, “full – fool”, “look – Luke”."],"k":[{"t":"look","ipa":"/lʊk/","vi":"nhìn, trông","a":"e09315fa02d7"},{"t":"good","ipa":"/ɡʊd/","vi":"tốt, đẹp","a":"fc19318dd131"},{"t":"took","ipa":"/tʊk/","vi":"đã chụp","a":"b1b416becb29"},{"t":"put","ipa":"/pʊt/","vi":"đặt, để","a":"132aeadf7367"},{"t":"zoom","ipa":"/zuːm/","vi":"phóng to","a":"92298812107b"},{"t":"view","ipa":"/vjuː/","vi":"quang cảnh","a":"8f3a07543988"},{"t":"blue","ipa":"/bluː/","vi":"màu xanh","a":"4c9a82ce72ca"},{"t":"beautiful","ipa":"/ˈbjuːtɪfl/","vi":"đẹp","a":"6393bcdfe36c"}],"r":[{"t":"months","ipa":"/mʌnθs/","vi":"tháng","a":"f1494311e45e","from":18},{"t":"while","ipa":"/waɪl/","vi":"trong khi","a":"6517f89c46c3","from":14}],"q":[{"q":"Do you like taking photos?","qa":"13770722b244","s":[{"t":"I do, especially of food and views.","a":"ec90245c9564"},{"t":"If a dish looks good, I have to take a quick shot before anyone moves.","a":"8ea158743267"},{"t":"My friends find it rude, but they still ask for the pictures.","a":"e44720cad03b"}]},{"q":"Do you prefer photos of people or of places?","qa":"824969b8737d","s":[{"t":"Places, usually.","a":"b77be8dbcdda"},{"t":"I took a beautiful one last June, with a full moon over a blue lake.","a":"b1d5dc4e2c7e"},{"t":"People are harder, because nobody looks natural when you zoom in.","a":"2beb118ec8ff"}]},{"q":"What do you do with the photos you take?","qa":"7e15f32a3a65","s":[{"t":"Most of them just sit on my phone, to be truthful.","a":"7673be694399"},{"t":"I put the good ones in an album and choose a few to print.","a":"6bd8dc18c265"},{"t":"There's a group photo from school on my bookshelf.","a":"e337111d719c"}]}]},{"w":23,"code":"PRON-023","g":"Nguyên âm","s":"/ɒ/ ngắn và /ɔː/ dài","t":"Art","tv":"Nghệ thuật","x":["Em hay đọc cả hai thành “o” tiếng Việt, không phân biệt ngắn – dài: “pot” và “port” nghe giống nhau.","/ɒ/: ngắn, há miệng rộng, môi hơi tròn: lot, hobby, modern.","/ɔː/: DÀI, môi tròn và đưa ra trước, miệng khép hơn: draw, wall, thought. Giọng Anh không đọc “r” trong “portrait”.","Tập đôi: “pot – port”, “shot – short”, “spot – sport”."],"k":[{"t":"lot","ipa":"/lɒt/","vi":"nhiều","a":"dcf6aa5497e0"},{"t":"hobby","ipa":"/ˈhɒbi/","vi":"sở thích","a":"54b7e849c6d2"},{"t":"pottery","ipa":"/ˈpɒtəri/","vi":"đồ gốm","a":"429d1859d182"},{"t":"modern","ipa":"/ˈmɒdn/","vi":"hiện đại","a":"b09be85d514f"},{"t":"draw","ipa":"/drɔː/","vi":"vẽ","a":"76a4e12c213d"},{"t":"wall","ipa":"/wɔːl/","vi":"bức tường","a":"eb7ada766135"},{"t":"thought","ipa":"/θɔːt/","vi":"đã nghĩ","a":"af93b3913b93"},{"t":"portrait","ipa":"/ˈpɔːtreɪt/","vi":"tranh chân dung","a":"25c604887316"}],"r":[{"t":"cheap","ipa":"/tʃiːp/","vi":"rẻ","a":"fb8df41a16b4","from":19},{"t":"thriller","ipa":"/ˈθrɪlə/","vi":"phim li kì","a":"952a08c42349","from":15}],"q":[{"q":"Do you like art?","qa":"37947b96e610","s":[{"t":"Quite a lot, although I'm not an expert.","a":"46f6c24b1003"},{"t":"I often stop to look at the paintings on café walls, and I follow a few artists online.","a":"b53487ed5c8d"}]},{"q":"Did you learn to draw at school?","qa":"14b437fa9ea6","s":[{"t":"We had one art lesson a week, mostly drawing pots and bottles.","a":"78c63fed2233"},{"t":"I thought it was boring at the time.","a":"3ee97566677a"},{"t":"Now I wish I'd got more out of it.","a":"aeb5b9c96d71"}]},{"q":"What kind of art would you put in your home?","qa":"97a4f0399d68","s":[{"t":"Nothing too modern.","a":"33e10b4ebf09"},{"t":"I'd want a small portrait of my dog in the hall and some pottery on a long shelf.","a":"f37624fc83b8"},{"t":"I saw a gorgeous blue pot in a shop last autumn.","a":"b0267e1bb0fa"}]}]},{"w":24,"code":"PRON-024","g":"Nguyên âm","s":"Âm /ə/ (schwa)","t":"Museums","tv":"Bảo tàng","x":["Em hay đọc rõ từng chữ cái ở âm tiết không nhấn: “about” thành “a-bao”, “famous” thành “phây-mớt”.","/ə/ là âm “ơ” rất NHẸ, ngắn, miệng thả lỏng hoàn toàn. Đây là âm nhiều nhất trong tiếng Anh.","Âm tiết không nhấn gần như luôn là /ə/: aBOUT, toDAY, FAmous, VIsitor.","Đọc âm nhấn to – dài, còn /ə/ lướt thật nhanh."],"k":[{"t":"about","ipa":"/əˈbaʊt/","vi":"về, khoảng","a":"5780daf6db0b"},{"t":"ago","ipa":"/əˈɡəʊ/","vi":"trước đây","a":"f03c0a59c594"},{"t":"today","ipa":"/təˈdeɪ/","vi":"hôm nay","a":"2dd2bed72567"},{"t":"famous","ipa":"/ˈfeɪməs/","vi":"nổi tiếng","a":"d923de9f6945"},{"t":"visitor","ipa":"/ˈvɪzɪtə/","vi":"khách tham quan","a":"4ed0428505b0"},{"t":"collection","ipa":"/kəˈlekʃn/","vi":"bộ sưu tập","a":"2037de437c80"},{"t":"museum","ipa":"/mjuˈziːəm/","vi":"bảo tàng","a":"5019bac93989"},{"t":"children","ipa":"/ˈtʃɪldrən/","vi":"trẻ em","a":"42685f11da91"}],"r":[{"t":"cat","ipa":"/kæt/","vi":"con mèo","a":"9d989e8d27dc","from":20},{"t":"paper","ipa":"/ˈpeɪpə/","vi":"giấy","a":"950593b1f42d","from":16}],"q":[{"q":"Do you like visiting museums?","qa":"163fb87e4352","s":[{"t":"I do, as long as there's a story to follow.","a":"053311781d40"},{"t":"A room of old pots isn't enough for me.","a":"131c6b7c6ca3"},{"t":"I want to know about the people who used them.","a":"4d031baa9ef5"}]},{"q":"Did you go to museums when you were a child?","qa":"b7d0e65f8fd1","s":[{"t":"Only on school trips.","a":"74a9bdb434e4"},{"t":"I remember a famous war museum we visited about ten years ago.","a":"a539fef02b52"},{"t":"The teachers talked and talked, and the children just wanted the gift shop.","a":"107f3e10c09c"}]},{"q":"Are museums popular with visitors to your country?","qa":"d686bbba7ed7","s":[{"t":"Some of them are.","a":"fb3cc2277a7d"},{"t":"The ethnology museum in Hanoi gets a lot of visitors, and its collection is excellent.","a":"4c7a998b3cf9"},{"t":"A few others are a bit old-fashioned and could do with some money.","a":"c75f735164e6"}]}]},{"w":25,"code":"PRON-025","g":"Nguyên âm","s":"Nguyên âm đôi /eɪ/ · /aɪ/ · /ɔɪ/","t":"Gifts","tv":"Quà tặng","x":["Em hay đọc nguyên âm đôi thành một âm đứng yên: “save” thành “sếp”, “price” thành “pờ-rai” cụt.","Nguyên âm đôi phải TRƯỢT từ âm thứ nhất sang âm thứ hai, âm đầu dài và rõ hơn.","/eɪ/: “ê” trượt sang “i” (save). /aɪ/: “a” trượt lên “i” (price). /ɔɪ/: “o” trượt sang “i” (choice).","Trượt xong vẫn phải bật âm cuối: “pri-ce”, “sa-ve”, “choi-ce”."],"k":[{"t":"save","ipa":"/seɪv/","vi":"tiết kiệm","a":"13a4a11319d3"},{"t":"handmade","ipa":"/ˌhændˈmeɪd/","vi":"làm bằng tay","a":"098f95f6b57a"},{"t":"price","ipa":"/praɪs/","vi":"giá","a":"2097c33723b6"},{"t":"surprise","ipa":"/səˈpraɪz/","vi":"bất ngờ","a":"63e76d7b9e50"},{"t":"buy","ipa":"/baɪ/","vi":"mua","a":"a066f070178f"},{"t":"choice","ipa":"/tʃɔɪs/","vi":"lựa chọn","a":"630af549b668"},{"t":"toy","ipa":"/tɔɪ/","vi":"đồ chơi","a":"cd1933db799b"},{"t":"disappointed","ipa":"/ˌdɪsəˈpɔɪntɪd/","vi":"thất vọng","a":"74699616123f"}],"r":[{"t":"love","ipa":"/lʌv/","vi":"yêu thích","a":"9f2feb0f1ef4","from":21},{"t":"traffic","ipa":"/ˈtræfɪk/","vi":"giao thông","a":"c8ab51895da8","from":17}],"q":[{"q":"Do you like giving gifts?","qa":"f7de2546a9d6","s":[{"t":"I love it, maybe more than getting them.","a":"52112f9cf5bf"},{"t":"I like to take my time and find something that fits the person.","a":"4f56f9da2b7b"},{"t":"Seeing the surprise on their face makes my day.","a":"4992438c7332"}]},{"q":"What was the last gift you received?","qa":"d6d2b750eb22","s":[{"t":"A handmade notebook from my best friend, with my name painted on the cover.","a":"811ac0fc8465"},{"t":"It can't have cost much, but I'd choose it over an expensive toy any day.","a":"91c75c43f0e8"}]},{"q":"Is it difficult to choose a gift?","qa":"8622cb6b1da3","s":[{"t":"Sometimes, yes.","a":"13cd2d39eca4"},{"t":"If I don't know the person's taste, I'm afraid they'll be disappointed.","a":"b1977ee00b9b"},{"t":"In that case I play safe and buy something nice to eat, whatever the price.","a":"b55b76823dc7"}]}]},{"w":26,"code":"PRON-026","g":"Nguyên âm","s":"Nguyên âm đôi /əʊ/ · /aʊ/","t":"Birthdays","tv":"Sinh nhật","x":["Em hay đọc /əʊ/ thành “ô” đứng yên (“home” thành “hôm”) và /aʊ/ thành “ao” cụt (“house” thành “hao”).","/əʊ/: bắt đầu bằng “ơ” rồi chu môi trượt sang “u”: home, phone, know.","/aʊ/: há miệng “a” rồi chu môi trượt sang “u”: house, round, loud.","Nhớ âm cuối sau khi trượt: “hou-se”, “rou-nd”, “pho-ne”."],"k":[{"t":"home","ipa":"/həʊm/","vi":"nhà","a":"e83249bd3ba7"},{"t":"phone","ipa":"/fəʊn/","vi":"điện thoại, gọi điện","a":"f6be6ca91098"},{"t":"know","ipa":"/nəʊ/","vi":"biết","a":"97accafb5337"},{"t":"grow","ipa":"/ɡrəʊ/","vi":"lớn lên","a":"c7c5d759817f"},{"t":"house","ipa":"/haʊs/","vi":"ngôi nhà","a":"5be93480bd8b"},{"t":"round","ipa":"/raʊnd/","vi":"sang chơi, vòng","a":"f0590a6dd366"},{"t":"loud","ipa":"/laʊd/","vi":"ồn ào","a":"d1c6f1a8165a"},{"t":"crowd","ipa":"/kraʊd/","vi":"đám đông","a":"c3bd87ad7652"}],"r":[{"t":"took","ipa":"/tʊk/","vi":"đã chụp","a":"b1b416becb29","from":22},{"t":"desk","ipa":"/desk/","vi":"bàn học","a":"46e7cfa08091","from":18}],"q":[{"q":"How do you usually celebrate your birthday?","qa":"5ca2ccf68a5d","s":[{"t":"Nothing showy.","a":"98e81af4c84e"},{"t":"I invite a few close friends round to my house, and we order food and blow out some candles.","a":"debd2bdf500d"},{"t":"I don't like a loud crowd.","a":"6d799758b248"}]},{"q":"What did you do on your last birthday?","qa":"d0f60539fc8e","s":[{"t":"I was away from home, so it was a low-key one.","a":"17d449ef5f88"},{"t":"My parents phoned in the morning.","a":"44a1e60e26b8"},{"t":"Then my flatmates took me out for a bowl of noodles downtown.","a":"218668201f1f"}]},{"q":"Are birthdays more important for children or adults?","qa":"64a8e7119a0a","s":[{"t":"For children, no doubt.","a":"6d1a14effa58"},{"t":"They count down the days and want the whole town to know.","a":"01aef6df90c2"},{"t":"As you grow older, you slow down and just hope someone remembers.","a":"45e364ae63ec"}]}]},{"w":27,"code":"PRON-027","g":"Trọng âm từ","s":"Danh từ, tính từ 2 âm tiết: nhấn âm đầu","t":"Neighbours","tv":"Hàng xóm","x":["Tiếng Việt đọc âm tiết nào cũng đều nhau nên em hay đọc “NEIGH-BOUR” hai âm bằng nhau.","Đa số danh từ và tính từ 2 âm tiết nhấn âm ĐẦU: NEIGHbour, NOIsy, PROBlem.","Âm được nhấn đọc TO hơn, CAO hơn, DÀI hơn. Âm còn lại đọc nhẹ và nhanh, thường là /ə/ hoặc /ɪ/.","Gõ tay theo nhịp MẠNH – nhẹ: “NEIGH-bour”, “LOVE-ly”."],"k":[{"t":"neighbour","ipa":"/ˈneɪbə/","vi":"hàng xóm","a":"b8a818857cbe"},{"t":"noisy","ipa":"/ˈnɔɪzi/","vi":"ồn ào","a":"e570e577ed48"},{"t":"problem","ipa":"/ˈprɒbləm/","vi":"vấn đề","a":"a5a0d15d4ae8"},{"t":"helpful","ipa":"/ˈhelpfl/","vi":"hay giúp đỡ","a":"4b7392910ae3"},{"t":"village","ipa":"/ˈvɪlɪdʒ/","vi":"làng","a":"3bdc3ec682bf"},{"t":"couple","ipa":"/ˈkʌpl/","vi":"cặp vợ chồng","a":"33fc2d930ae9"},{"t":"building","ipa":"/ˈbɪldɪŋ/","vi":"toà nhà","a":"b8114546a306"},{"t":"lovely","ipa":"/ˈlʌvli/","vi":"dễ mến","a":"de3460832ea0"}],"r":[{"t":"modern","ipa":"/ˈmɒdn/","vi":"hiện đại","a":"b09be85d514f","from":23},{"t":"team","ipa":"/tiːm/","vi":"đội","a":"d25187dc137f","from":19}],"q":[{"q":"Do you know your neighbours?","qa":"44b7a17847f3","s":[{"t":"Most of them, yes.","a":"3b29c88af164"},{"t":"There's a lovely older couple next door who've known me since I was a baby.","a":"3458929f21e5"},{"t":"We're not best friends, but we always stop for a chat.","a":"1db935457414"}]},{"q":"How often do you see them?","qa":"95270740c312","s":[{"t":"Nearly every morning.","a":"955acf9e0cae"},{"t":"We share a narrow alley, so I can't leave the building without passing someone's kitchen window.","a":"951bef49f67b"},{"t":"People here are very open.","a":"569e1ffd6dcc"}]},{"q":"Have you ever had a problem with a neighbour?","qa":"0d6dacecd17d","s":[{"t":"Only a minor one.","a":"acf1f2fa8244"},{"t":"The family upstairs had a noisy puppy, and it barked at night for a fortnight.","a":"cd49c266da3a"},{"t":"My mother had a quiet word, and they were really helpful about it.","a":"e8d82d39b230"}]}]},{"w":28,"code":"PRON-028","g":"Trọng âm từ","s":"Động từ 2 âm tiết: nhấn âm thứ hai","t":"Travel","tv":"Du lịch","x":["Em hay nhấn âm đầu ở mọi từ: “A-rrive”, “PRE-fer”, “HO-tel”.","Đa số động từ 2 âm tiết nhấn âm THỨ HAI: arRIVE, exPLORE, preFER, forGET, deCIDE.","Âm đầu đọc thật nhẹ (/ə/, /ɪ/), dồn hơi vào âm sau, kéo dài và lên giọng.","Một vài danh từ, trạng từ cũng nhấn âm hai: hoTEL, aBROAD."],"k":[{"t":"arrive","ipa":"/əˈraɪv/","vi":"đến nơi","a":"163001e29033"},{"t":"explore","ipa":"/ɪkˈsplɔː/","vi":"khám phá","a":"9dda9754b3ee"},{"t":"prefer","ipa":"/prɪˈfɜː/","vi":"thích hơn","a":"866e90dff0f0"},{"t":"forget","ipa":"/fəˈɡet/","vi":"quên","a":"b96cfac54be6"},{"t":"decide","ipa":"/dɪˈsaɪd/","vi":"quyết định","a":"d14809f05ad6"},{"t":"return","ipa":"/rɪˈtɜːn/","vi":"trở về","a":"63143b6f8007"},{"t":"abroad","ipa":"/əˈbrɔːd/","vi":"ở nước ngoài","a":"5fcf5cdf976e"},{"t":"hotel","ipa":"/həʊˈtel/","vi":"khách sạn","a":"14e833557d06"}],"r":[{"t":"visitor","ipa":"/ˈvɪzɪtə/","vi":"khách tham quan","a":"4ed0428505b0","from":24},{"t":"rabbit","ipa":"/ˈræbɪt/","vi":"con thỏ","a":"6d0ebbbdce32","from":20}],"q":[{"q":"Do you like travelling?","qa":"028fffd12793","s":[{"t":"Very much.","a":"6b70d8bb211e"},{"t":"I love that first hour when you arrive somewhere new and begin to explore.","a":"24d6b410c7d5"},{"t":"I always forget my worries the minute I unpack.","a":"437fdcb92bf6"}]},{"q":"Do you prefer travelling alone or with others?","qa":"2af29e65e50e","s":[{"t":"I prefer to go with one or two friends.","a":"48515253b231"},{"t":"You can divide the cost of the hotel, and it's easier to decide what to do.","a":"d35eb39f0cee"},{"t":"Big groups just argue.","a":"7121d1eb1b7e"}]},{"q":"Where would you like to go in the future?","qa":"51f0838c3dee","s":[{"t":"I'd love to go abroad, perhaps to Japan.","a":"e535ddb44d43"},{"t":"I'd begin in Kyoto and explore the old streets on foot.","a":"6ed515b64715"},{"t":"I doubt I'd want to return home.","a":"3f26c2bd4f7d"}]}]},{"w":29,"code":"PRON-029","g":"Trọng âm từ","s":"Từ có đuôi -tion / -sion: nhấn ngay trước đuôi","t":"Holidays","tv":"Kì nghỉ","x":["Em hay nhấn sai ở từ dài: “DES-ti-na-tion”, “ce-LE-bra-tion”.","Quy tắc: từ có đuôi -tion/-sion luôn nhấn âm tiết NGAY TRƯỚC đuôi: destiNAtion, traDItion, deCIsion.","Đuôi -tion đọc /ʃn/ rất nhẹ (“sần”), -sion sau nguyên âm đọc /ʒn/. Không đọc “sừn” hay “ti-ôn”.","Từ dài có thêm một nhấn phụ ở phía trước: ˌcele‑ˈbra‑tion."],"k":[{"t":"tradition","ipa":"/trəˈdɪʃn/","vi":"truyền thống","a":"56d99310d246"},{"t":"destination","ipa":"/ˌdestɪˈneɪʃn/","vi":"điểm đến","a":"0cf1bc84bb8b"},{"t":"reservation","ipa":"/ˌrezəˈveɪʃn/","vi":"việc đặt chỗ","a":"bcf112ef0115"},{"t":"celebration","ipa":"/ˌselɪˈbreɪʃn/","vi":"lễ kỉ niệm","a":"b7bdf51b880e"},{"t":"accommodation","ipa":"/əˌkɒməˈdeɪʃn/","vi":"chỗ ở","a":"65b0cfa2ea6d"},{"t":"location","ipa":"/ləʊˈkeɪʃn/","vi":"địa điểm","a":"6469ac84a897"},{"t":"decision","ipa":"/dɪˈsɪʒn/","vi":"quyết định","a":"8501a34f34de"},{"t":"occasion","ipa":"/əˈkeɪʒn/","vi":"dịp","a":"84eeb8492554"}],"r":[{"t":"choice","ipa":"/tʃɔɪs/","vi":"lựa chọn","a":"630af549b668","from":25},{"t":"calm","ipa":"/kɑːm/","vi":"dịu, bình yên","a":"2ec3d0c752de","from":21}],"q":[{"q":"What do you usually do on holiday?","qa":"4bd1a17cea6f","s":[{"t":"It's a bit of a family tradition to go to the coast.","a":"2e9de3a36215"},{"t":"We pick a destination in spring and make a reservation.","a":"4c0a34422c82"},{"t":"Then we spend a week doing very little.","a":"38149e504e41"}]},{"q":"What's the most important holiday in your country?","qa":"91e5ca2f67f8","s":[{"t":"Tet, without question.","a":"206b8218c613"},{"t":"It's a celebration of the new year, and it's the one occasion when the whole family gets together.","a":"d19e13142ac3"},{"t":"Preparation starts weeks ahead.","a":"3601ec03d8aa"}]},{"q":"Do you prefer short breaks or long holidays?","qa":"8bbdf1f5f591","s":[{"t":"Short breaks, on reflection.","a":"a9a6970404e3"},{"t":"Accommodation costs less for a few nights, and there's less organisation involved.","a":"b2a7270165ee"},{"t":"Three days in a nice location is enough for me.","a":"c287f1590ac1"}]}]},{"w":30,"code":"PRON-030","g":"Trọng âm từ","s":"Đuôi -ic: nhấn ngay trước · đuôi -ity: nhấn âm thứ ba từ cuối","t":"Languages","tv":"Ngôn ngữ","x":["Em hay giữ trọng âm của từ gốc: “A-ca-de-mic”, “AC-ti-vi-ty”.","Đuôi -ic: nhấn âm tiết ngay trước nó: fanTAStic, acaDEmic, speCIfic.","Đuôi -ity: nhấn âm tiết ngay trước -ity: aBIlity, acTIvity, uniVERsity, opporTUnity.","Trọng âm đổi chỗ khi thêm đuôi: ACtive → acTIvity; ABle → aBIlity."],"k":[{"t":"fantastic","ipa":"/fænˈtæstɪk/","vi":"tuyệt vời","a":"3be18d81b31f"},{"t":"specific","ipa":"/spəˈsɪfɪk/","vi":"cụ thể","a":"660cffc21b66"},{"t":"academic","ipa":"/ˌækəˈdemɪk/","vi":"học thuật","a":"27bc2c56988f"},{"t":"realistic","ipa":"/ˌriːəˈlɪstɪk/","vi":"thực tế","a":"4dad68295a4c"},{"t":"ability","ipa":"/əˈbɪləti/","vi":"khả năng","a":"083dbabef569"},{"t":"activity","ipa":"/ækˈtɪvəti/","vi":"hoạt động","a":"0bf4170444cd"},{"t":"university","ipa":"/ˌjuːnɪˈvɜːsəti/","vi":"đại học","a":"f9f914060ccb"},{"t":"opportunity","ipa":"/ˌɒpəˈtjuːnəti/","vi":"cơ hội","a":"198e7188b0b1"}],"r":[{"t":"loud","ipa":"/laʊd/","vi":"ồn ào","a":"d1c6f1a8165a","from":26},{"t":"blue","ipa":"/bluː/","vi":"màu xanh","a":"4c9a82ce72ca","from":22}],"q":[{"q":"What languages can you speak?","qa":"bacc93a453d4","s":[{"t":"Vietnamese is my mother tongue, and I've been learning English since primary school.","a":"225d02de7c63"},{"t":"My speaking ability is decent, but my academic writing needs work.","a":"d6fe3d9e383c"}]},{"q":"Why are you learning English?","qa":"10cd369fd1d0","s":[{"t":"For a specific reason: I want to go to university abroad.","a":"a024f472e5ad"},{"t":"A good IELTS score gives me the opportunity to apply, so it's a very realistic goal.","a":"52f7606a16cd"}]},{"q":"What's the best way to learn a language?","qa":"6f8d01df70ae","s":[{"t":"Use it for an activity you already enjoy.","a":"68af82d0b67b"},{"t":"I watch cooking videos in English, which is fantastic for my listening.","a":"04705f10ea46"},{"t":"Textbooks help, but real life gives you more opportunities to practise.","a":"7e45d6f18b27"}]}]},{"w":31,"code":"PRON-031","g":"Trọng âm từ","s":"Hậu tố không đổi trọng âm: -er, -or, -ly, -ful, -ness, -ment","t":"Teachers","tv":"Thầy cô","x":["Khi từ dài ra, em hay chuyển trọng âm về cuối: “care-ful-LY”, “im-prove-MENT”.","Các hậu tố -er, -or, -ly, -ful, -ness, -ment KHÔNG làm đổi trọng âm: giữ nguyên như từ gốc.","beGIN → beGINner; CAREful → CAREfully; imPROVE → imPROVEment; sucCESS → sucCESSful.","Hậu tố luôn đọc nhẹ, nhanh, thường có /ə/: /-mənt/, /-nəs/, /-fl/."],"k":[{"t":"beginner","ipa":"/bɪˈɡɪnə/","vi":"người mới học","a":"9fbd11cb3717"},{"t":"instructor","ipa":"/ɪnˈstrʌktə/","vi":"người hướng dẫn","a":"5db3005d1c92"},{"t":"carefully","ipa":"/ˈkeəfəli/","vi":"một cách cẩn thận","a":"00f74c9df553"},{"t":"properly","ipa":"/ˈprɒpəli/","vi":"đàng hoàng, đúng cách","a":"6348da66ade7"},{"t":"kindness","ipa":"/ˈkaɪndnəs/","vi":"sự tử tế","a":"67b889b2ec5c"},{"t":"successful","ipa":"/səkˈsesfl/","vi":"thành công","a":"33375351bc25"},{"t":"improvement","ipa":"/ɪmˈpruːvmənt/","vi":"sự tiến bộ","a":"a1e3124328de"},{"t":"encouragement","ipa":"/ɪnˈkʌrɪdʒmənt/","vi":"sự động viên","a":"d0e72539d327"}],"r":[{"t":"lovely","ipa":"/ˈlʌvli/","vi":"dễ mến","a":"de3460832ea0","from":27},{"t":"portrait","ipa":"/ˈpɔːtreɪt/","vi":"tranh chân dung","a":"25c604887316","from":23}],"q":[{"q":"Do you have a favourite teacher?","qa":"b47686b03757","s":[{"t":"Yes, my literature teacher from year ten.","a":"cd2d6d3cbb18"},{"t":"She explained everything carefully.","a":"a91e4c32c0f5"},{"t":"Her kindness made even the quiet students feel comfortable in class.","a":"d42e1e78350e"}]},{"q":"What makes a good teacher?","qa":"0c6fcf05b778","s":[{"t":"Patience, mainly.","a":"f4b76b8da423"},{"t":"A good teacher treats every beginner with respect and notices small improvements.","a":"5b3ff151e8d3"},{"t":"A bit of encouragement goes a long way.","a":"1407da911743"}]},{"q":"Would you like to be a teacher?","qa":"72a34bcbd249","s":[{"t":"I'm not sure I'd be successful at it.","a":"a1094b885752"},{"t":"I can explain things properly to one person, but thirty teenagers is another matter.","a":"968bf03e8572"},{"t":"Maybe I could be a swimming instructor instead.","a":"55676e6b5cd8"}]}]},{"w":32,"code":"PRON-032","g":"Trọng âm từ","s":"Từ 3–4 âm tiết: thường nhấn âm thứ ba từ cuối","t":"Maths","tv":"Môn Toán","x":["Với từ dài, em hay nhấn âm cuối hoặc đọc đều: “cal-cu-LATE”, “dif-fi-CULT”.","Nhiều từ 3–4 âm tiết (đuôi -ate, -ise, -y, -al…) nhấn âm thứ BA tính từ cuối: CALculate, MULtiply, geOmetry, LOgical.","Âm ngay sau trọng âm đọc rất nhẹ, gần như biến mất: “DIF-fi-cult”, “AV-rage”.","Đuôi -ate ở động từ đọc /eɪt/ rõ nhưng KHÔNG nhấn."],"k":[{"t":"calculate","ipa":"/ˈkælkjuleɪt/","vi":"tính toán","a":"a8f700e7c0a3"},{"t":"multiply","ipa":"/ˈmʌltɪplaɪ/","vi":"nhân","a":"07fcd2c2e5fc"},{"t":"memorise","ipa":"/ˈmeməraɪz/","vi":"học thuộc","a":"58592585d1de"},{"t":"difficult","ipa":"/ˈdɪfɪkəlt/","vi":"khó","a":"d2a26f03aa5a"},{"t":"logical","ipa":"/ˈlɒdʒɪkl/","vi":"hợp lô-gíc","a":"38dd66928079"},{"t":"practical","ipa":"/ˈpræktɪkl/","vi":"thực tế","a":"7f55aa8957ff"},{"t":"average","ipa":"/ˈævərɪdʒ/","vi":"trung bình","a":"93a8018f99fa"},{"t":"geometry","ipa":"/dʒiˈɒmətri/","vi":"hình học","a":"ff63fac4076c"}],"r":[{"t":"arrive","ipa":"/əˈraɪv/","vi":"đến nơi","a":"163001e29033","from":28},{"t":"about","ipa":"/əˈbaʊt/","vi":"về, khoảng","a":"5780daf6db0b","from":24}],"q":[{"q":"Do you like maths?","qa":"78631aa08dad","s":[{"t":"I do, as it happens.","a":"0a27ab525fa9"},{"t":"I like subjects with a logical answer.","a":"75dadef77226"},{"t":"It's satisfying when a difficult problem finally works out.","a":"60a2b295ef8c"}]},{"q":"Did you find maths difficult at school?","qa":"6bdb29c92dac","s":[{"t":"Algebra was fine, but geometry gave me a headache.","a":"de1518e39fd7"},{"t":"I had to memorise dozens of formulas, and my marks were only average that year.","a":"5ac8b63250e6"}]},{"q":"Do you use maths in your daily life?","qa":"6e9a26c29926","s":[{"t":"Only the practical bits.","a":"979f21c519ac"},{"t":"I calculate my change at the market and multiply prices when there's a sale.","a":"2077df6d40fb"},{"t":"For anything bigger, I reach for my phone.","a":"795a0b7c5825"}]}]},{"w":33,"code":"PRON-033","g":"Trọng âm từ","s":"Danh từ ghép: nhấn từ đầu","t":"Science","tv":"Khoa học","x":["Em hay nhấn cả hai phần hoặc nhấn phần sau: “class-ROOM”, “text-BOOK”.","Danh từ ghép (hai từ gộp thành một danh từ) nhấn phần ĐẦU: CLASSroom, TEXTbook, GREENhouse.","Phần sau đọc thấp giọng và nhanh hơn nhưng vẫn đủ âm.","So sánh: a GREENhouse (nhà kính) khác a green HOUSE (ngôi nhà màu xanh)."],"k":[{"t":"classroom","ipa":"/ˈklɑːsruːm/","vi":"lớp học","a":"be45c8f0f4f7"},{"t":"textbook","ipa":"/ˈtekstbʊk/","vi":"sách giáo khoa","a":"796bee182f91"},{"t":"notebook","ipa":"/ˈnəʊtbʊk/","vi":"vở","a":"5280933cbca1"},{"t":"sunlight","ipa":"/ˈsʌnlaɪt/","vi":"ánh nắng","a":"1f4ae04738c5"},{"t":"greenhouse","ipa":"/ˈɡriːnhaʊs/","vi":"nhà kính","a":"ffedc28b1cb4"},{"t":"earthquake","ipa":"/ˈɜːθkweɪk/","vi":"động đất","a":"e8dea393aacb"},{"t":"rainforest","ipa":"/ˈreɪnfɒrɪst/","vi":"rừng mưa","a":"7a7ef5b1b149"},{"t":"spaceship","ipa":"/ˈspeɪsʃɪp/","vi":"tàu vũ trụ","a":"6900a064deb1"}],"r":[{"t":"destination","ipa":"/ˌdestɪˈneɪʃn/","vi":"điểm đến","a":"0cf1bc84bb8b","from":29},{"t":"handmade","ipa":"/ˌhændˈmeɪd/","vi":"làm bằng tay","a":"098f95f6b57a","from":25}],"q":[{"q":"Do you enjoy science?","qa":"6aa23ee2e063","s":[{"t":"Yes, more than most subjects.","a":"a4b236068e06"},{"t":"I like it when we leave the textbook and do something with our hands.","a":"0ee7853a7ba8"},{"t":"Last term we grew beans in a little greenhouse behind the classroom.","a":"5c2af711c3bb"}]},{"q":"What did you learn in science at school?","qa":"28cd360c5624","s":[{"t":"All sorts.","a":"cb40a97fa5f7"},{"t":"I remember a project on earthquakes and another on why the rainforest matters.","a":"c7dd4b65bfe1"},{"t":"I filled a whole notebook with drawings of volcanoes.","a":"5d401a3a801a"}]},{"q":"Is there a science topic you'd like to know more about?","qa":"2497812fe792","s":[{"t":"Space, definitely.","a":"69dea9d9f338"},{"t":"I'd like to understand how a spaceship gets back to Earth in one piece.","a":"b8d91a4caab4"},{"t":"I watch a lot of clips on it, but the maths in the background loses me.","a":"ff0e4ff0d844"}]}]},{"w":34,"code":"PRON-034","g":"Trọng âm từ","s":"Cùng một từ: danh từ nhấn âm đầu, động từ nhấn âm sau","t":"Internet","tv":"Internet","x":["Em hay đọc danh từ và động từ giống hệt nhau: “record” lúc nào cũng “RE-cord”.","Một số từ đổi trọng âm theo từ loại. Danh từ nhấn âm ĐẦU: a REcord, a PREsent, an INcrease.","Động từ nhấn âm SAU: to reCORD, to preSENT, to inCREASE. Âm đầu yếu đi thành /rɪ/, /prɪ/, /ɪn/.","Động từ thời Internet cũng nhấn âm sau: upLOAD, downLOAD."],"k":[{"t":"a record","ipa":"/ə ˈrekɔːd/","vi":"một kỉ lục","a":"ac4326d97469"},{"t":"to record","ipa":"/tə rɪˈkɔːd/","vi":"ghi âm","a":"e85da775e15b"},{"t":"a present","ipa":"/ə ˈpreznt/","vi":"một món quà","a":"8ad941aec96d"},{"t":"to present","ipa":"/tə prɪˈzent/","vi":"trình bày","a":"cecc5dcdf535"},{"t":"an increase","ipa":"/ən ˈɪŋkriːs/","vi":"sự gia tăng","a":"6d14eac280c9"},{"t":"to increase","ipa":"/tu ɪnˈkriːs/","vi":"tăng lên","a":"81c286f02aa1"},{"t":"website","ipa":"/ˈwebsaɪt/","vi":"trang web","a":"3ab3e0b020a6"},{"t":"download","ipa":"/ˌdaʊnˈləʊd/","vi":"tải xuống","a":"817248fb77fb"}],"r":[{"t":"academic","ipa":"/ˌækəˈdemɪk/","vi":"học thuật","a":"27bc2c56988f","from":30},{"t":"know","ipa":"/nəʊ/","vi":"biết","a":"97accafb5337","from":26}],"q":[{"q":"How often do you use the internet?","qa":"1b4b1ce49b12","s":[{"t":"All day, if I'm honest.","a":"2f4ae731b8bf"},{"t":"I record voice notes for friends, download songs and check a couple of websites for news.","a":"8ee594dacf6b"},{"t":"My screen time is a personal record this month.","a":"cccd43d1f10b"}]},{"q":"What do you mainly use it for?","qa":"8e531778d96b","s":[{"t":"Mostly for school.","a":"72bc0a1d52c0"},{"t":"We have to present a project every month, so I research online and upload my slides.","a":"601ea8e4035d"},{"t":"I also follow a channel that presents science in a fun way.","a":"5a218ed29e3e"}]},{"q":"Has the internet changed the way you study?","qa":"b432e5f1e39d","s":[{"t":"Hugely.","a":"179f7bd5ca44"},{"t":"There's been a big increase in online courses, and they've increased my confidence a lot.","a":"ec34307fc1ca"},{"t":"I can replay a lesson until it makes sense.","a":"ab54afe2adf2"}]}]},{"w":35,"code":"PRON-035","g":"Nhịp câu & nối âm","s":"Trọng âm câu: nhấn từ mang nghĩa","t":"Sleep","tv":"Giấc ngủ","x":["Em hay đọc từng từ to và đều như nhau, nghe như đọc chính tả.","Tiếng Anh chỉ nhấn các từ MANG NGHĨA: danh từ, động từ chính, tính từ, trạng từ, từ phủ định (*in đậm* trong bài).","Các từ chức năng (a, the, to, of, at, I, my, and…) đọc nhẹ, nhanh, lướt qua.","Gõ tay vào các từ in đậm, khoảng cách giữa các lần gõ gần bằng nhau."],"k":[{"t":"go to bed","ipa":"/ˌɡəʊ tə ˈbed/","vi":"đi ngủ","a":"9a3de76ff621"},{"t":"fall asleep","ipa":"/ˌfɔːl əˈsliːp/","vi":"ngủ thiếp đi","a":"a96986bd4115"},{"t":"wake up early","ipa":"/ˌweɪk ʌp ˈɜːli/","vi":"dậy sớm","a":"af945255b454"},{"t":"stay up late","ipa":"/ˌsteɪ ʌp ˈleɪt/","vi":"thức khuya","a":"0cf874b71307"},{"t":"have a nap","ipa":"/ˌhæv ə ˈnæp/","vi":"ngủ trưa một lát","a":"41c35ec9741a"},{"t":"a good night's sleep","ipa":"/ə ˌɡʊd naɪts ˈsliːp/","vi":"một giấc ngủ ngon","a":"3ef71f844dc6"}],"r":[{"t":"properly","ipa":"/ˈprɒpəli/","vi":"đàng hoàng, đúng cách","a":"6348da66ade7","from":31},{"t":"helpful","ipa":"/ˈhelpfl/","vi":"hay giúp đỡ","a":"4b7392910ae3","from":27}],"q":[{"q":"How many hours do you sleep each night?","qa":"8369621d9298","s":[{"t":"About *seven*, on a *good* *night*.","a":"859520496adb"},{"t":"I *go* to *bed* at *eleven* and *wake* up at *six*.","a":"d8c621ccf41a"},{"t":"It's *not* really *enough* for me.","a":"fe478d9d60ef"}]},{"q":"Do you ever have a nap during the day?","qa":"75b20833efd1","s":[{"t":"*Only* at *weekends*.","a":"1bb0777bd231"},{"t":"I have a *nap* after *lunch*, for *half* an *hour* at *most*.","a":"77fd5dde63dd"},{"t":"If I *sleep* any *longer*, I *can't* fall *asleep* at *night*.","a":"eac70a97ee25"}]},{"q":"What do you do if you can't sleep?","qa":"34f35f8d55e4","s":[{"t":"I *put* my *phone* in *another* *room* and *read* a *few* *pages* of a *book*.","a":"f617f3d1d6ed"},{"t":"If *that* doesn't *work*, I *listen* to the *rain* on an *app*.","a":"eeda85d9033f"}]}]},{"w":36,"code":"PRON-036","g":"Nhịp câu & nối âm","s":"Dạng yếu (1): a, the, of, to, for, and, at","t":"Health","tv":"Sức khoẻ","x":["Em hay đọc rõ từng từ nhỏ: “cup OF tea” với “of” là “óp”, “to” là “tu”.","Trong câu, các từ này chuyển sang dạng YẾU với âm /ə/: a /ə/, the /ðə/, of /əv/, to /tə/, for /fə/, and /ən/, at /ət/.","Đọc dạng yếu thật nhẹ và dính vào từ bên cạnh: “a cup of tea” = /ə ˌkʌp əv ˈtiː/.","Nhờ vậy các từ quan trọng mới nổi lên và câu có nhịp tự nhiên."],"k":[{"t":"a cup of tea","ipa":"/ə ˌkʌp əv ˈtiː/","vi":"một tách trà","a":"188fb9eaec75"},{"t":"a lot of water","ipa":"/ə ˌlɒt əv ˈwɔːtə/","vi":"nhiều nước","a":"f7e163d95e0b"},{"t":"fruit and vegetables","ipa":"/ˌfruːt ən ˈvedʒtəblz/","vi":"rau củ quả","a":"d46cf735fbda"},{"t":"go to the gym","ipa":"/ˌɡəʊ tə ðə ˈdʒɪm/","vi":"đi tập gym","a":"e11743c7ee22"},{"t":"good for you","ipa":"/ˈɡʊd fə ju/","vi":"tốt cho bạn","a":"5ceb7772aa24"},{"t":"at the weekend","ipa":"/ət ðə ˌwiːkˈend/","vi":"vào cuối tuần","a":"cf6988aa9751"}],"r":[{"t":"logical","ipa":"/ˈlɒdʒɪkl/","vi":"hợp lô-gíc","a":"38dd66928079","from":32},{"t":"decide","ipa":"/dɪˈsaɪd/","vi":"quyết định","a":"d14809f05ad6","from":28}],"q":[{"q":"How do you keep healthy?","qa":"585cc1936de4","s":[{"t":"I try to eat a lot of fruit and vegetables, and I go to the gym at the weekend.","a":"83a17aae2059"},{"t":"I also drink a couple of litres of water a day.","a":"43a80627fb6b"}]},{"q":"Is it easy to stay healthy where you live?","qa":"3413eb193759","s":[{"t":"It's easier than it used to be.","a":"b356bc4aea90"},{"t":"There are a few parks for people to exercise in, and the food at the market is fresh.","a":"4adfe7318c99"},{"t":"The air is the real problem.","a":"0b7e5c5b8990"}]},{"q":"Have your habits changed over the years?","qa":"afe6cb4cd96b","s":[{"t":"For the better, I think.","a":"4eb1f1845332"},{"t":"I used to live on cans of cola and bags of crisps.","a":"fe7413e670ff"},{"t":"Now I have a cup of green tea and some nuts for a snack.","a":"23939420ce0f"}]}]},{"w":37,"code":"PRON-037","g":"Nhịp câu & nối âm","s":"Dạng yếu (2): can, was, were, do, have, them","t":"Cooking","tv":"Nấu ăn","x":["Em hay đọc trợ động từ thật rõ: “I CAN cook”, “I WAS hungry” — nghe như đang nhấn mạnh.","Trong câu khẳng định, chúng ở dạng YẾU: can /kən/, was /wəz/, were /wə/, do /də/, have /əv/, them /ðəm/.","“I can cook” = /aɪ kən ˈkʊk/: nhấn “cook”, không nhấn “can”.","Chỉ đọc dạng mạnh khi đứng cuối câu hoặc khi phủ định: “Yes, I can.” – “I can't.”"],"k":[{"t":"I can cook.","ipa":"/aɪ kən ˈkʊk/","vi":"Tôi biết nấu ăn.","a":"937e55e2c87b"},{"t":"What do you cook?","ipa":"/ˌwɒt də ju ˈkʊk/","vi":"Bạn nấu món gì?","a":"3cd5a2fbe688"},{"t":"I was hungry.","ipa":"/aɪ wəz ˈhʌŋɡri/","vi":"Tôi đã đói.","a":"da12488dd606"},{"t":"We were late.","ipa":"/wi wə ˈleɪt/","vi":"Chúng tôi đã muộn.","a":"bed9bee4e1e1"},{"t":"I should have asked.","ipa":"/aɪ ʃəd əv ˈɑːskt/","vi":"Lẽ ra tôi nên hỏi.","a":"deb87e405333"},{"t":"Tell them.","ipa":"/ˈtel ðəm/","vi":"Nói với họ đi.","a":"e4ec499c0f12"}],"r":[{"t":"earthquake","ipa":"/ˈɜːθkweɪk/","vi":"động đất","a":"e8dea393aacb","from":33},{"t":"location","ipa":"/ləʊˈkeɪʃn/","vi":"địa điểm","a":"6469ac84a897","from":29}],"q":[{"q":"Can you cook?","qa":"ccf3ffa457fe","s":[{"t":"I can make a few simple dishes.","a":"5c1d2bdcd9ef"},{"t":"My mum was a chef, so there were always lessons going on at home.","a":"67929bd38b1b"},{"t":"I should have paid more attention.","a":"965e7f2810e0"}]},{"q":"Who does the cooking in your family?","qa":"385195ccb0b7","s":[{"t":"My dad does most of it.","a":"52e0cc13fe6f"},{"t":"He was taught by his mother, and he can turn leftovers into a proper meal.","a":"d04ddfecbf1d"},{"t":"The rest of us just do the washing-up.","a":"4e42b1ee11bf"}]},{"q":"What was the last meal you cooked?","qa":"9860565bd97d","s":[{"t":"It was fried rice, two nights ago.","a":"addb4f148739"},{"t":"My parents were out and I was starving.","a":"b7429cbeae54"},{"t":"I must have used every pan in the kitchen, but it tasted fine.","a":"72958a3004d9"}]}]},{"w":38,"code":"PRON-038","g":"Nhịp câu & nối âm","s":"Nối âm: phụ âm cuối + nguyên âm đầu","t":"Housework","tv":"Việc nhà","x":["Em hay ngắt rời từng từ: “pick | it | up”, nên nghe cứng và dễ rơi âm cuối.","Khi một từ kết thúc bằng phụ âm và từ sau bắt đầu bằng nguyên âm, hãy NỐI phụ âm đó sang: pick‿it‿up → “pi-ki-tup”.","Nối âm cũng giúp em giữ được âm cuối: wash‿up → “wo-shup”, once‿a week → “wun-sə week”.","Trong bài, dấu ‿ cho biết chỗ cần nối."],"k":[{"t":"clean‿up","ipa":"/ˌkliːn ˈʌp/","vi":"dọn sạch","a":"6a5b8322571e"},{"t":"wash‿up","ipa":"/ˌwɒʃ ˈʌp/","vi":"rửa bát","a":"cc782551ae17"},{"t":"pick‿it‿up","ipa":"/ˌpɪk ɪt ˈʌp/","vi":"nhặt nó lên","a":"c5ce97e9fae0"},{"t":"put‿it‿away","ipa":"/ˌpʊt ɪt əˈweɪ/","vi":"cất nó đi","a":"cb31056130cb"},{"t":"once‿a week","ipa":"/ˌwʌns ə ˈwiːk/","vi":"một lần một tuần","a":"b8cfcd4adb5a"},{"t":"a bit‿of‿a mess","ipa":"/ə ˌbɪt əv ə ˈmes/","vi":"hơi bừa bộn","a":"7da71ce2ae3d"}],"r":[{"t":"website","ipa":"/ˈwebsaɪt/","vi":"trang web","a":"3ab3e0b020a6","from":34},{"t":"university","ipa":"/ˌjuːnɪˈvɜːsəti/","vi":"đại học","a":"f9f914060ccb","from":30}],"q":[{"q":"Do you help with the housework?","qa":"7e0aff506989","s":[{"t":"I do my share.","a":"ec4b4d7d68c3"},{"t":"I wash‿up‿after dinner and take‿out the rubbish, and I clean my room once‿a week.","a":"e7adf79c9938"},{"t":"That's‿about‿it, though.","a":"fb0dc1357a92"}]},{"q":"Which chores do you dislike?","qa":"4ea2b357e1d8","s":[{"t":"Ironing, more than‿anything.","a":"3c60f43d7b2f"},{"t":"It takes‿ages, and‿I always miss‿a bit.","a":"62f4d1d36fba"},{"t":"I'd rather sweep‿a whole house than‿iron‿a single shirt.","a":"25efe16df7c0"}]},{"q":"Did you do chores when you were a child?","qa":"3fa4d3bcd69f","s":[{"t":"Yes, from‿an‿early age.","a":"60e6537f8509"},{"t":"If‿I left‿a toy on the floor, I had to pick‿it‿up‿and put‿it‿away.","a":"f898ddef8242"},{"t":"It was‿a good habit to get‿into.","a":"d89b670f4379"}]}]},{"w":39,"code":"PRON-039","g":"Nhịp câu & nối âm","s":"Nối âm: nguyên âm + nguyên âm (/j/, /w/, /r/)","t":"Plants","tv":"Cây cối","x":["Khi hai nguyên âm đứng cạnh nhau, em hay ngắt hơi ở giữa: “go | outside”, “very | easy”.","Người bản xứ chêm một âm lướt nhỏ để nối: sau /iː ɪ eɪ aɪ/ thêm /j/: very‿easy → “very-yeasy”.","Sau /uː əʊ aʊ/ thêm /w/: go‿outside → “go-woutside”, two‿or three → “two-wor three”.","Chữ r cuối từ được đọc lại khi theo sau là nguyên âm: water‿it /ˈwɔːtər ɪt/, for‿a while /fər ə ˈwaɪl/."],"k":[{"t":"very‿easy","ipa":"/ˌveri (j)ˈiːzi/","vi":"rất dễ","a":"63c795aaa292"},{"t":"the‿orchid","ipa":"/ði (j)ˈɔːkɪd/","vi":"cây lan","a":"69bebf4a0c64"},{"t":"go‿outside","ipa":"/ˌɡəʊ (w)aʊtˈsaɪd/","vi":"ra ngoài","a":"6d62b968622d"},{"t":"two‿or three","ipa":"/ˌtuː (w)ɔː ˈθriː/","vi":"hai hoặc ba","a":"9a6cbc59ce60"},{"t":"water‿it","ipa":"/ˈwɔːtər ɪt/","vi":"tưới nó","a":"a4cb8d1a3088"},{"t":"for‿a while","ipa":"/fər ə ˈwaɪl/","vi":"một lúc","a":"2581eb0a53ce"}],"r":[{"t":"stay up late","ipa":"/ˌsteɪ ʌp ˈleɪt/","vi":"thức khuya","a":"0cf874b71307","from":35},{"t":"encouragement","ipa":"/ɪnˈkʌrɪdʒmənt/","vi":"sự động viên","a":"d0e72539d327","from":31}],"q":[{"q":"Do you have any plants at home?","qa":"1e2043162e10","s":[{"t":"Yes, two‿or three on my balcony.","a":"0a78c8250282"},{"t":"There's a cactus, a little‿orange tree‿and‿a pot‿of basil.","a":"c8e28bdb43f0"},{"t":"They're very‿easy to look‿after.","a":"2160b76e8e1e"}]},{"q":"Do you know how to grow plants?","qa":"dd4e78251133","s":[{"t":"Only the‿easy ones.","a":"0d90a09ee816"},{"t":"With my basil, I water‿it when the soil is dry and keep‿it by the window.","a":"6e98377b4982"},{"t":"For‿anything harder, I‿ask my grandmother.","a":"eadfb574f637"}]},{"q":"Would you like to have a garden?","qa":"87cebf09cad4","s":[{"t":"I'd love one.","a":"5c058535015b"},{"t":"I'd grow‿a few herbs and maybe‿a lemon tree.","a":"33e0f7972d49"},{"t":"Then I'd sit there‿in the‿evening for‿a while.","a":"ef6dec84339b"}]}]},{"w":40,"code":"PRON-040","g":"Nhịp câu & nối âm","s":"Nuốt âm /t/, /d/ giữa hai phụ âm","t":"Noise","tv":"Tiếng ồn","x":["Em cố bật thật rõ mọi /t/, /d/ nên bị vấp: “next‑tờ door”, “last‑tờ night”.","Khi /t/ hoặc /d/ kẹt giữa hai phụ âm, người bản xứ thường LƯỚT BỎ nó: next door → /ˌneks ˈdɔː/, last night → /ˌlɑːs ˈnaɪt/.","Tương tự: must be → /ˈmʌs bi/, I don't know → /aɪ ˌdəʊn ˈnəʊ/, old man → /ˌəʊl ˈmæn/.","Lưu ý: chỉ bỏ khi đứng GIỮA hai phụ âm. Trước nguyên âm hoặc cuối câu vẫn phải bật: “the last‿one”, “It's next.”"],"k":[{"t":"next door","ipa":"/ˌneks ˈdɔː/","vi":"nhà bên cạnh","a":"e1308cb61b86"},{"t":"last night","ipa":"/ˌlɑːs ˈnaɪt/","vi":"tối qua","a":"715021f9795c"},{"t":"must be","ipa":"/ˈmʌs bi/","vi":"chắc hẳn là","a":"64a9244dfa64"},{"t":"just now","ipa":"/ˌdʒʌs ˈnaʊ/","vi":"vừa nãy","a":"a7f8e7cc0d43"},{"t":"old man","ipa":"/ˌəʊl ˈmæn/","vi":"ông cụ","a":"997ebf5f4639"},{"t":"I don't know","ipa":"/aɪ ˌdəʊn ˈnəʊ/","vi":"tôi không biết","a":"c02a68f5c2a3"}],"r":[{"t":"good for you","ipa":"/ˈɡʊd fə ju/","vi":"tốt cho bạn","a":"5ceb7772aa24","from":36},{"t":"calculate","ipa":"/ˈkælkjuleɪt/","vi":"tính toán","a":"a8f700e7c0a3","from":32}],"q":[{"q":"Is it noisy where you live?","qa":"9e765fb02c23","s":[{"t":"It can be.","a":"692a2ea71c66"},{"t":"The people next door are having their kitchen rebuilt, so the drilling starts at eight.","a":"829632ea2a91"},{"t":"Last night was the first quiet one in weeks.","a":"d06a600797e1"}]},{"q":"What kinds of noise bother you?","qa":"2e0e64fdd764","s":[{"t":"Loud music late at night, mostly.","a":"fc187f9e88d3"},{"t":"I don't mind traffic, because I've lived with it all my life.","a":"472ef567afd6"},{"t":"But a thumping bass next door just drives me mad.","a":"6e61cf8d5821"}]},{"q":"Do you need silence when you study?","qa":"0a7fb5168963","s":[{"t":"I used to think so, but I'm not so sure now.","a":"a62d3d5e8121"},{"t":"Soft background music helps me focus.","a":"90198df4abba"},{"t":"It must be instrumental, though, or I end up singing along.","a":"dee380440d09"}]}]},{"w":41,"code":"PRON-041","g":"Nhịp câu & nối âm","s":"Dạng rút gọn: I'm, I've, I'd, I'll, it's, there's","t":"Patience","tv":"Sự kiên nhẫn","x":["Em hay đọc tách “I am”, “I have”, “I will” — nghe như đang đọc văn bản, hoặc bỏ luôn âm cuối: “I'll” thành “ai”.","Khi nói, dùng dạng rút gọn và đọc thành MỘT âm tiết: I'm /aɪm/, I've /aɪv/, I'd /aɪd/, I'll /aɪl/.","Âm cuối nhỏ nhưng phải có: mím môi /m/, răng chạm môi /v/, chạm lưỡi /d/, /l/.","it's /ɪts/, there's /ðeəz/, they've /ðeɪv/ cũng đọc liền một hơi."],"k":[{"t":"I'm waiting.","ipa":"/aɪm ˈweɪtɪŋ/","vi":"Tôi đang đợi.","a":"8f81fbc6883d"},{"t":"I've learnt.","ipa":"/aɪv ˈlɜːnt/","vi":"Tôi đã học được.","a":"cdd1bc2362bf"},{"t":"I'd say.","ipa":"/aɪd ˈseɪ/","vi":"Tôi nghĩ là.","a":"d3454a7ba6a3"},{"t":"I'll try.","ipa":"/aɪl ˈtraɪ/","vi":"Tôi sẽ thử.","a":"d603baf56a9a"},{"t":"It's worth it.","ipa":"/ɪts ˈwɜːθ ɪt/","vi":"Đáng mà.","a":"b9823838f481"},{"t":"There's no rush.","ipa":"/ðeəz ˌnəʊ ˈrʌʃ/","vi":"Không vội gì.","a":"cee95748272f"}],"r":[{"t":"Tell them.","ipa":"/ˈtel ðəm/","vi":"Nói với họ đi.","a":"e4ec499c0f12","from":37},{"t":"textbook","ipa":"/ˈtekstbʊk/","vi":"sách giáo khoa","a":"796bee182f91","from":33}],"q":[{"q":"Are you a patient person?","qa":"410e8ed28a5f","s":[{"t":"I'd say I'm fairly patient with people, but not with machines.","a":"07cb4a35e7bd"},{"t":"If my laptop's slow, I'll start tapping the desk within seconds.","a":"c70b85e172f8"},{"t":"It's something I'm working on.","a":"a102fd65a3c6"}]},{"q":"When do you find it hard to be patient?","qa":"2031016cc61f","s":[{"t":"When I'm hungry and there's a long queue.","a":"37023afc6396"},{"t":"I've walked out of restaurants because of it.","a":"b3b8bf8122a5"},{"t":"My friends think it's funny, but they've learnt to feed me first.","a":"45f58ff81845"}]},{"q":"Have you become more patient as you've got older?","qa":"e10c76c2d267","s":[{"t":"I think I have.","a":"de7e5c0918ad"},{"t":"I've realised that most things aren't worth getting upset about.","a":"0b9698a8324e"},{"t":"If the bus is late, there's no rush: I'll just read for ten minutes.","a":"3e11197ce509"}]}]},{"w":42,"code":"PRON-042","g":"Nhịp câu & nối âm","s":"Rút gọn phủ định: can't, don't, doesn't, isn't, won't","t":"Being on time","tv":"Đúng giờ","x":["Em hay đọc “can” và “can't” giống nhau, người nghe hiểu ngược ý.","can (khẳng định) đọc YẾU /kən/ và không nhấn. can't đọc MẠNH, dài: /kɑːnt/ — luôn được nhấn.","Các dạng phủ định luôn nhấn: don't /dəʊnt/, doesn't /ˈdʌznt/, isn't /ˈɪznt/, won't /wəʊnt/.","Phải nghe được /n/ và hơi chặn của /t/ ở cuối: “don't”, không phải “đâu”."],"k":[{"t":"I can be there.","ipa":"/aɪ kən ˈbiː ðeə/","vi":"Tôi đến được.","a":"3c8d47445a37"},{"t":"I can't stand it.","ipa":"/aɪ ˌkɑːnt ˈstænd ɪt/","vi":"Tôi không chịu nổi.","a":"584efe8de94c"},{"t":"I don't mind.","ipa":"/aɪ ˌdəʊnt ˈmaɪnd/","vi":"Tôi không phiền.","a":"0fbc5a33556b"},{"t":"It doesn't matter.","ipa":"/ɪt ˌdʌznt ˈmætə/","vi":"Không sao cả.","a":"1a693ca27cda"},{"t":"I wasn't late.","ipa":"/aɪ ˌwɒznt ˈleɪt/","vi":"Tôi đã không muộn.","a":"74993027e688"},{"t":"They won't wait.","ipa":"/ðeɪ ˌwəʊnt ˈweɪt/","vi":"Họ sẽ không đợi.","a":"22326c206c91"}],"r":[{"t":"clean‿up","ipa":"/ˌkliːn ˈʌp/","vi":"dọn sạch","a":"6a5b8322571e","from":38},{"t":"a present","ipa":"/ə ˈpreznt/","vi":"một món quà","a":"8ad941aec96d","from":34}],"q":[{"q":"Are you usually on time?","qa":"9109814c1925","s":[{"t":"Nearly always.","a":"6d9761214f72"},{"t":"I can't relax if I'm running late, so I leave early.","a":"259c0e988bda"},{"t":"My friends aren't the same, and it doesn't seem to bother them.","a":"24b9956fa237"}]},{"q":"How do you feel when other people are late?","qa":"9b8a9ab5f759","s":[{"t":"I don't mind five or ten minutes.","a":"8dbad7896cf1"},{"t":"What I can't stand is when someone doesn't even send a message.","a":"23a9feb2c107"},{"t":"It isn't hard to text and say sorry.","a":"d6ada7c35ee7"}]},{"q":"Is being on time important in your country?","qa":"299d57c206b2","s":[{"t":"It depends.","a":"dab83e0236f2"},{"t":"You can't be late for school or work, and trains won't wait for anyone.","a":"0b3d7d7e000c"},{"t":"For a coffee with friends, though, people don't worry much.","a":"16e31f4e168e"}]}]},{"w":43,"code":"PRON-043","g":"Ngữ điệu & ngắt ý","s":"Xuống giọng ở cuối câu trả lời","t":"Social media","tv":"Mạng xã hội","x":["Em hay giữ giọng ngang hoặc lên giọng ở cuối mọi câu, nghe như đang hỏi lại hoặc chưa nói xong.","Câu trần thuật kết thúc bằng giọng XUỐNG ↘ ở từ quan trọng cuối cùng: “Every day ↘.”","Xuống giọng dứt khoát cho thấy em tự tin và đã nói hết ý.","Tập: nói từ cuối cao lên một chút rồi thả rơi xuống: “my friends ↘”."],"k":[{"t":"Every day ↘","ipa":"/ˌevri ˈdeɪ/","vi":"Ngày nào cũng vậy.","a":"3b2eb5131055"},{"t":"Not really ↘","ipa":"/ˌnɒt ˈriːəli/","vi":"Không hẳn.","a":"aa1816fca9d5"},{"t":"It depends ↘","ipa":"/ɪt dɪˈpendz/","vi":"Còn tuỳ.","a":"251be2f8fb5a"},{"t":"I love it ↘","ipa":"/aɪ ˈlʌv ɪt/","vi":"Tôi rất thích.","a":"685e7048467b"},{"t":"Mostly at night ↘","ipa":"/ˌməʊstli ət ˈnaɪt/","vi":"Chủ yếu vào buổi tối.","a":"95602ac6e117"},{"t":"That's all ↘","ipa":"/ˌðæts ˈɔːl/","vi":"Chỉ vậy thôi.","a":"3d296d3b8280"}],"r":[{"t":"the‿orchid","ipa":"/ði (j)ˈɔːkɪd/","vi":"cây lan","a":"69bebf4a0c64","from":39},{"t":"fall asleep","ipa":"/ˌfɔːl əˈsliːp/","vi":"ngủ thiếp đi","a":"a96986bd4115","from":35}],"q":[{"q":"Do you use social media?","qa":"faa37d7c7952","s":[{"t":"Every day ↘.","a":"acae2b1b6405"},{"t":"I mainly use it to keep up with my friends ↘.","a":"783d7bfd740f"},{"t":"I don't post much myself ↘.","a":"45ab06a86752"}]},{"q":"Which apps do you use most?","qa":"237263ca69f8","s":[{"t":"Instagram, without a doubt ↘.","a":"49ce25aae782"},{"t":"I like looking at travel photos ↘.","a":"a43f4bcb0680"},{"t":"I also use Zalo to talk to my family ↘.","a":"f9905695c247"}]},{"q":"Do you think you spend too much time on it?","qa":"a31a8385896e","s":[{"t":"Probably ↘.","a":"511edaa7619d"},{"t":"I check my phone as soon as I wake up ↘.","a":"4e83d6b019b7"},{"t":"So I've set a limit of one hour a day ↘.","a":"42e27f220f7a"}]}]},{"w":44,"code":"PRON-044","g":"Ngữ điệu & ngắt ý","s":"Lên giọng khi chưa hết ý, xuống giọng khi kết thúc","t":"Advertisements","tv":"Quảng cáo","x":["Em hay xuống giọng ngay sau cụm mở đầu, làm người nghe tưởng em đã nói xong.","Sau cụm mở đầu hoặc mệnh đề phụ (To be honest, If…, When…), giọng hơi LÊN ↗ để báo “còn nữa”.","Đến cuối ý chính mới XUỐNG ↘: “To be honest ↗, not very much ↘.”","Lên nhẹ thôi, không cao như câu hỏi."],"k":[{"t":"To be honest ↗","ipa":"/tə bi ˈɒnɪst/","vi":"Thật lòng mà nói,","a":"fafab92afeea"},{"t":"In my opinion ↗","ipa":"/ɪn ˌmaɪ əˈpɪnjən/","vi":"Theo tôi,","a":"b43191a1b360"},{"t":"Most of the time ↗","ipa":"/ˌməʊst əv ðə ˈtaɪm/","vi":"Phần lớn thời gian,","a":"259eb1d4e04e"},{"t":"When I'm online ↗","ipa":"/wen aɪm ˌɒnˈlaɪn/","vi":"Khi tôi lên mạng,","a":"f7209cbe3094"},{"t":"If it's funny ↗","ipa":"/ɪf ɪts ˈfʌni/","vi":"Nếu nó hài,","a":"2c139679f6f3"},{"t":"As far as I know ↗","ipa":"/əz ˌfɑːr əz aɪ ˈnəʊ/","vi":"Theo tôi biết,","a":"1066a1d7241f"}],"r":[{"t":"must be","ipa":"/ˈmʌs bi/","vi":"chắc hẳn là","a":"64a9244dfa64","from":40},{"t":"fruit and vegetables","ipa":"/ˌfruːt ən ˈvedʒtəblz/","vi":"rau củ quả","a":"d46cf735fbda","from":36}],"q":[{"q":"Do you like watching advertisements?","qa":"c70fe1e1bdb7","s":[{"t":"To be honest ↗, not very much ↘.","a":"9276948bf352"},{"t":"If an advert is funny ↗, I'll watch it to the end ↘.","a":"d910b26c5939"},{"t":"Most of the time ↗, I just press skip ↘.","a":"56920c070b50"}]},{"q":"Where do you see the most adverts?","qa":"002e6bdcff0e","s":[{"t":"When I'm online ↗, they're everywhere ↘.","a":"33623d131523"},{"t":"Before a video starts ↗, there are usually two or three ↘.","a":"8171ce7f3acc"},{"t":"On the street ↗, I hardly notice them any more ↘.","a":"28d458d267cd"}]},{"q":"Have you ever bought something because of an advert?","qa":"b2306e06a46f","s":[{"t":"Once or twice ↗, yes ↘.","a":"6007a8678577"},{"t":"Last year ↗, I saw an advert for running shoes and ordered them the same day ↘.","a":"5977804decfc"},{"t":"As it turned out ↗, they were excellent ↘.","a":"0ddd98f48aff"}]}]},{"w":45,"code":"PRON-045","g":"Ngữ điệu & ngắt ý","s":"Ngữ điệu khi liệt kê và khi lựa chọn","t":"Money","tv":"Tiền bạc","x":["Khi liệt kê, em hay đọc đều một giọng nên người nghe không biết danh sách hết ở đâu.","Mỗi mục trong danh sách LÊN giọng ↗, riêng mục cuối cùng XUỐNG ↘: food ↗, books ↗ and bus fares ↘.","Câu lựa chọn với “or”: lên ở vế đầu, xuống ở vế sau: cash ↗ or card ↘.","Nghỉ một nhịp rất ngắn sau mỗi mục."],"k":[{"t":"food ↗, books ↗ and clothes ↘","ipa":"/ˈfuːd ˈbʊks ən ˈkləʊðz/","vi":"đồ ăn, sách và quần áo","a":"ad80f197473f"},{"t":"rent ↗, bills ↗ and transport ↘","ipa":"/ˈrent ˈbɪlz ən ˈtrænspɔːt/","vi":"tiền nhà, hoá đơn và đi lại","a":"0eb396a4fd2c"},{"t":"cash ↗ or card ↘","ipa":"/ˈkæʃ ɔː ˈkɑːd/","vi":"tiền mặt hay thẻ","a":"6f0edbcadcef"},{"t":"now ↗ or later ↘","ipa":"/ˈnaʊ ɔː ˈleɪtə/","vi":"bây giờ hay để sau","a":"662ad205650c"},{"t":"tea ↗ or coffee ↘","ipa":"/ˈtiː ɔː ˈkɒfi/","vi":"trà hay cà phê","a":"ed384668c8f6"},{"t":"a little ↗ or a lot ↘","ipa":"/ə ˈlɪtl ɔːr ə ˈlɒt/","vi":"một chút hay nhiều","a":"4ac6786045e8"}],"r":[{"t":"I'll try.","ipa":"/aɪl ˈtraɪ/","vi":"Tôi sẽ thử.","a":"d603baf56a9a","from":41},{"t":"We were late.","ipa":"/wi wə ˈleɪt/","vi":"Chúng tôi đã muộn.","a":"bed9bee4e1e1","from":37}],"q":[{"q":"What do you spend most of your money on?","qa":"0a7ffa65d927","s":[{"t":"Three things, really: food ↗, books ↗ and bus fares ↘.","a":"e83ca61e3dd8"},{"t":"I don't buy many clothes ↘.","a":"6da9c2bbd69f"},{"t":"What's left goes on coffee ↗, snacks ↗ and the odd cinema ticket ↘.","a":"e23ac6538ae4"}]},{"q":"Do you prefer paying by cash or by card?","qa":"de7830f4f366","s":[{"t":"It depends on where I am ↘.","a":"a2f41c6d3e4a"},{"t":"At the market ↗, at street stalls ↗ and in small cafés ↗, I pay cash ↘.","a":"f7e67fe65a20"},{"t":"Everywhere else ↗, I just use my phone ↘.","a":"2cb8d9022327"}]},{"q":"Are you good at saving money?","qa":"47d472805c83","s":[{"t":"I'm getting better ↘.","a":"aeeb62f5252b"},{"t":"Each month I put a little aside for emergencies ↗, for presents ↗ and for a summer trip ↘.","a":"1365d14e5698"},{"t":"It's not a fortune ↗, but it adds up ↘.","a":"d5146d7f838c"}]}]},{"w":46,"code":"PRON-046","g":"Ngữ điệu & ngắt ý","s":"Ngắt câu theo cụm ý (chunking)","t":"Environment","tv":"Môi trường","x":["Em hay đọc một mạch đến khi hết hơi, hoặc ngắt sau từng từ — cả hai đều khó nghe.","Chia câu thành các CỤM Ý ngắn 3–6 từ và nghỉ rất ngắn giữa các cụm (dấu / trong bài).","Ngắt ở sau chủ ngữ dài, trước liên từ (and, but, when), trước và sau cụm chỉ nơi chốn, thời gian.","Không ngắt giữa mạo từ – danh từ hay giới từ – danh từ: “in my neighbourhood” đi liền một hơi."],"k":[{"t":"in my neighbourhood","ipa":"/ɪn maɪ ˈneɪbəhʊd/","vi":"ở khu tôi sống","a":"dc92af6b13e0"},{"t":"as much as I can","ipa":"/əz ˌmʌtʃ əz aɪ ˈkæn/","vi":"nhiều nhất có thể","a":"1c10c5150964"},{"t":"on the way to school","ipa":"/ɒn ðə ˌweɪ tə ˈskuːl/","vi":"trên đường đến trường","a":"e6666f961107"},{"t":"instead of plastic bags","ipa":"/ɪnˌsted əv ˌplæstɪk ˈbæɡz/","vi":"thay cho túi ni lông","a":"a8a4b1692b22"},{"t":"at least once a week","ipa":"/ət ˌliːst wʌns ə ˈwiːk/","vi":"ít nhất một lần một tuần","a":"65ad486c8ec9"},{"t":"for the next generation","ipa":"/fə ðə ˌnekst ˌdʒenəˈreɪʃn/","vi":"cho thế hệ sau","a":"ffafbf10269c"}],"r":[{"t":"I wasn't late.","ipa":"/aɪ ˌwɒznt ˈleɪt/","vi":"Tôi đã không muộn.","a":"74993027e688","from":42},{"t":"once‿a week","ipa":"/ˌwʌns ə ˈwiːk/","vi":"một lần một tuần","a":"b8cfcd4adb5a","from":38}],"q":[{"q":"Do you care about the environment?","qa":"f756e5156cdb","s":[{"t":"I do / and I try to help / as much as I can.","a":"7c28767c0370"},{"t":"I carry a cloth bag / instead of plastic ones / and I take my own bottle / wherever I go.","a":"059baf9c8fd1"}]},{"q":"Is there much pollution where you live?","qa":"e7c6ba3ec670","s":[{"t":"Quite a lot / I'm afraid.","a":"4d1240b5cf69"},{"t":"In my neighbourhood / the air is at its worst / early in the morning / when everyone is on the way to work.","a":"a73998ba161a"}]},{"q":"What do you do to protect the environment?","qa":"dabf188e51f9","s":[{"t":"Small things / mostly.","a":"624f6edd7fcd"},{"t":"I sort the rubbish / at least once a week / and I cycle to school / when the weather is fine.","a":"8fe71f72d0dd"},{"t":"It isn't much / but it's a start.","a":"c9c89eca1177"}]}]},{"w":47,"code":"PRON-047","g":"Ngữ điệu & ngắt ý","s":"Nhấn mạnh để so sánh, đối lập","t":"Future plans","tv":"Dự định tương lai","x":["Em hay nhấn mọi từ như nhau nên người nghe không biết ý nào là quan trọng nhất.","Khi muốn ĐỐI LẬP hai ý, nhấn thật mạnh vào hai từ được so sánh (*in đậm*): abroad, not at home.","Từ được nhấn mạnh đọc to hơn, cao hơn và kéo dài; các từ xung quanh nhẹ đi.","“do / does / did” cũng dùng để nhấn mạnh: “I *do* love my hometown.”"],"k":[{"t":"abroad, not at *home*","ipa":"/əˈbrɔːd nɒt ət ˈhəʊm/","vi":"ở nước ngoài, không phải trong nước","a":"7fd74cfaa4db"},{"t":"*my* decision, not *theirs*","ipa":"/ˈmaɪ dɪˌsɪʒn nɒt ˈðeəz/","vi":"quyết định của tôi, không phải của họ","a":"ef73df3cdea5"},{"t":"not *this* year, *next* year","ipa":"/nɒt ˈðɪs jɪə ˈnekst jɪə/","vi":"không phải năm nay, mà năm sau","a":"87242b63f3f0"},{"t":"I *do* want to","ipa":"/aɪ ˈduː wɒnt tə/","vi":"tôi thật sự muốn","a":"fb8fdc63a99e"},{"t":"*really* important","ipa":"/ˈriːəli ɪmˈpɔːtnt/","vi":"thật sự quan trọng","a":"7beb618116cc"},{"t":"the *first* step","ipa":"/ðə ˈfɜːst step/","vi":"bước đầu tiên","a":"c57a2f7fe09f"}],"r":[{"t":"That's all ↘","ipa":"/ˌðæts ˈɔːl/","vi":"Chỉ vậy thôi.","a":"3d296d3b8280","from":43},{"t":"for‿a while","ipa":"/fər ə ˈwaɪl/","vi":"một lúc","a":"2581eb0a53ce","from":39}],"q":[{"q":"What are your plans for the next few years?","qa":"ae4be6fe30ce","s":[{"t":"I want to study *abroad*, not at *home*.","a":"1a050b951adf"},{"t":"My parents wanted me to do *medicine*, but I've chosen *design*.","a":"23cfb3a4b110"},{"t":"It was *my* decision, not *theirs*.","a":"3891fa2f3793"}]},{"q":"Do you prefer to plan ahead or be spontaneous?","qa":"a4e268e91fd9","s":[{"t":"For *big* things, I plan.","a":"4a10a0047c46"},{"t":"For *small* things, I really don't.","a":"e5b402a5f1c5"},{"t":"I know *where* I want to be in five years, just not *how* I'll get there.","a":"a313766d6d8f"}]},{"q":"Will you stay in your hometown in the future?","qa":"5d3064d6e8ef","s":[{"t":"Not *straight* away.","a":"b55bed0385ac"},{"t":"I'd like to work in a *big* city first, and *then* come back.","a":"749849a84b6b"},{"t":"I *do* love my hometown, but there aren't many *jobs* there.","a":"23e24888b7b4"}]}]},{"w":48,"code":"PRON-048","g":"Ngữ điệu & ngắt ý","s":"Nói có cảm xúc: mở rộng cao độ, kết hợp lên – xuống – ngắt","t":"Happiness","tv":"Hạnh phúc","x":["Em hay nói một giọng đều đều, nghe như đang đọc thuộc lòng và thiếu hứng thú.","Mở đầu câu trả lời bằng giọng CAO hơn bình thường, rồi xuống dần: “Oh, simple things ↘.”","Kết hợp mọi thứ đã học: lên ↗ khi chưa hết ý, xuống ↘ khi kết thúc, ngắt / giữa các cụm.","Mỉm cười khi nói — giọng sẽ tự sáng và có lên xuống hơn."],"k":[{"t":"Oh, definitely!","ipa":"/əʊ ˈdefɪnətli/","vi":"Ồ, chắc chắn rồi!","a":"c464361c9d9d"},{"t":"Absolutely!","ipa":"/ˌæbsəˈluːtli/","vi":"Hoàn toàn đúng!","a":"62717b736a38"},{"t":"That's a good question.","ipa":"/ˌðæts ə ɡʊd ˈkwestʃən/","vi":"Câu hỏi hay đấy.","a":"30622c45a247"},{"t":"Well, it depends.","ipa":"/wel ɪt dɪˈpendz/","vi":"À, còn tuỳ.","a":"eb1e5d8c1c90"},{"t":"I'd say so, yes.","ipa":"/aɪd ˈseɪ səʊ jes/","vi":"Tôi nghĩ là vậy.","a":"63cf101348a5"},{"t":"Not at all.","ipa":"/ˌnɒt ət ˈɔːl/","vi":"Hoàn toàn không.","a":"b2ff0612ad27"}],"r":[{"t":"To be honest ↗","ipa":"/tə bi ˈɒnɪst/","vi":"Thật lòng mà nói,","a":"fafab92afeea","from":44},{"t":"next door","ipa":"/ˌneks ˈdɔː/","vi":"nhà bên cạnh","a":"e1308cb61b86","from":40}],"q":[{"q":"What makes you happy?","qa":"c4775119db4f","s":[{"t":"Oh, simple things ↘.","a":"04ce9ac2089e"},{"t":"A good meal with my family ↗, a sunny morning ↗, or a message from an old friend ↘.","a":"43f0c98e2e1f"},{"t":"I don't need much / to be in a good mood ↘.","a":"94fc00941985"}]},{"q":"Are you happier now than when you were a child?","qa":"7244938c13c7","s":[{"t":"That's a good question ↘.","a":"30622c45a247"},{"t":"As a child ↗, I had no worries at all ↘.","a":"8a61485e0e6e"},{"t":"Now I have more freedom ↗, and I'd say that matters more ↘.","a":"d03d0bfaa4a4"}]},{"q":"Do you think money can make people happy?","qa":"1a6d40183387","s":[{"t":"Well, it depends ↘.","a":"eb1e5d8c1c90"},{"t":"If you can't pay your rent ↗, money is everything ↘.","a":"ba30b2a410f3"},{"t":"Beyond that ↗, I think time with people you love / is worth far more ↘.","a":"c440947bb92e"}]}]},{"w":49,"code":"PRON-049","g":"Ôn tập tổng hợp","s":"Ôn tập 1: âm cuối, phụ âm khó, nguyên âm (tuần 1–26)","t":"About you","tv":"Về bản thân em","x":["Bài kiểm tra tổng hợp phần ÂM. Không có lỗi mới — em dùng lại tất cả những gì đã luyện.","Kiểm tra 1: mọi âm cuối /t d k p s z l n ŋ/ và đuôi -s, -ed đều phải nghe thấy.","Kiểm tra 2: /θ ð ʃ tʃ dʒ z v r/ đúng vị trí lưỡi – môi; cụm phụ âm đọc đủ, không chêm “ờ”.","Kiểm tra 3: nguyên âm dài – ngắn rõ ràng, nguyên âm đôi phải trượt."],"k":[{"t":"street","ipa":"/striːt/","vi":"con phố","a":"d3a9fb075d49"},{"t":"crowded","ipa":"/ˈkraʊdɪd/","vi":"đông đúc","a":"8bd8c4facee3"},{"t":"watches","ipa":"/ˈwɒtʃɪz/","vi":"xem","a":"59fe6817258b"},{"t":"decided","ipa":"/dɪˈsaɪdɪd/","vi":"đã quyết định","a":"d4b8ee99930d"},{"t":"healthy","ipa":"/ˈhelθi/","vi":"lành mạnh","a":"de18ccfa15e8"},{"t":"together","ipa":"/təˈɡeðə/","vi":"cùng nhau","a":"9034ff9e2b8f"},{"t":"friends","ipa":"/frendz/","vi":"bạn bè","a":"3d9209c4598b"},{"t":"thriller","ipa":"/ˈθrɪlə/","vi":"phim li kì","a":"952a08c42349"}],"r":[{"t":"rent ↗, bills ↗ and transport ↘","ipa":"/ˈrent ˈbɪlz ən ˈtrænspɔːt/","vi":"tiền nhà, hoá đơn và đi lại","a":"0eb396a4fd2c","from":45},{"t":"I've learnt.","ipa":"/aɪv ˈlɜːnt/","vi":"Tôi đã học được.","a":"cdd1bc2362bf","from":41}],"q":[{"q":"Can you tell me about where you live?","qa":"aa27f907716f","s":[{"t":"I live with my parents in a crowded part of the city.","a":"ed82b7c70d05"},{"t":"Our street is noisy during the day, but it's close to the shops and my school.","a":"feb0c2dc8182"},{"t":"I can't complain.","a":"329f58be0fda"}]},{"q":"What do you do in your free time?","qa":"86cbe775729a","s":[{"t":"I'm into swimming and old films.","a":"7ea5eadcfa77"},{"t":"On Thursdays I go to the pool with three friends.","a":"87e46cb10578"},{"t":"At the weekend we usually watch something together at my house.","a":"2af1eb4c1797"}]},{"q":"What did you do last weekend?","qa":"93c2458e6fb1","s":[{"t":"On Saturday I visited my grandmother and helped her in the garden.","a":"811345832ca4"},{"t":"Then I stayed in, finished my homework and watched a thriller until midnight.","a":"7da8400baed4"}]}]},{"w":50,"code":"PRON-050","g":"Ôn tập tổng hợp","s":"Ôn tập 2: trọng âm, nối âm, ngữ điệu (tuần 27–48)","t":"Looking ahead","tv":"Hướng tới tương lai","x":["Bài kiểm tra tổng hợp phần NHỊP và NGỮ ĐIỆU. Em đọc như đang trả lời giám khảo thật.","Trọng âm từ đúng chỗ; trong câu chỉ nhấn từ mang nghĩa (*in đậm*), từ chức năng đọc dạng yếu.","Nối âm ở dấu ‿, dùng dạng rút gọn (I'd, I'll, I've, can't).","Ngắt ở dấu /, lên giọng ↗ khi chưa hết ý và xuống ↘ khi kết thúc."],"k":[{"t":"destination","ipa":"/ˌdestɪˈneɪʃn/","vi":"điểm đến","a":"0cf1bc84bb8b"},{"t":"university","ipa":"/ˌjuːnɪˈvɜːsəti/","vi":"đại học","a":"f9f914060ccb"},{"t":"to record","ipa":"/tə rɪˈkɔːd/","vi":"ghi âm","a":"e85da775e15b"},{"t":"a cup of tea","ipa":"/ə ˌkʌp əv ˈtiː/","vi":"một tách trà","a":"188fb9eaec75"},{"t":"pick‿it‿up","ipa":"/ˌpɪk ɪt ˈʌp/","vi":"nhặt nó lên","a":"c5ce97e9fae0"},{"t":"last night","ipa":"/ˌlɑːs ˈnaɪt/","vi":"tối qua","a":"715021f9795c"},{"t":"I can't stand it.","ipa":"/aɪ ˌkɑːnt ˈstænd ɪt/","vi":"Tôi không chịu nổi.","a":"584efe8de94c"},{"t":"Not at all.","ipa":"/ˌnɒt ət ˈɔːl/","vi":"Hoàn toàn không.","a":"b2ff0612ad27"}],"r":[{"t":"on the way to school","ipa":"/ɒn ðə ˌweɪ tə ˈskuːl/","vi":"trên đường đến trường","a":"e6666f961107","from":46},{"t":"I don't mind.","ipa":"/aɪ ˌdəʊnt ˈmaɪnd/","vi":"Tôi không phiền.","a":"0fbc5a33556b","from":42}],"q":[{"q":"What do you usually do in the evening?","qa":"de70f5b23a45","s":[{"t":"After dinner ↗, I wash‿up and do my homework ↘.","a":"6480c9505a23"},{"t":"If there's time left ↗, I have a cup‿of tea / and watch a film with my sister ↘.","a":"aadcaeef5d5c"}]},{"q":"Do you prefer studying alone or with friends?","qa":"83b2aa4af8d5","s":[{"t":"*Alone*, most of the time ↘.","a":"7bb526939ebb"},{"t":"I can't concentrate / when people are chatting ↘.","a":"12cdef659a52"},{"t":"Before an exam, though ↗, I like to revise with *one* friend ↘.","a":"628cf03688ad"}]},{"q":"What would you like to do in the future?","qa":"8282d3699e0a","s":[{"t":"I'd like to go to university abroad ↗, perhaps in Australia ↘.","a":"67d724babc7f"},{"t":"It's a big decision ↗, but I've thought‿about‿it a lot ↘.","a":"2ae8ca8c294d"},{"t":"I'll need a good IELTS score first ↘.","a":"2a7d54104259"}]}]}];
